EjC,+BAAgC,CAGhC,cAAe,CAFf,6BAA8B,CAC9B,qCAAsC,CAPtC,WAAY,CACZ,wBAAyB,CAQzB,mHACJ,CAEI,yCACI,8CAA+C,CAC/C,sCACJ,CAEA,6BAEI,cAAe,CADf,WAEJ,CAEJ,4BAGI,yCAA0C,CAD1C,uCAAwC,CADxC,yBAGJ,CAEI,iDAEI,2CAA4C,CAD5C,gCAEJ,CCpJJ,gBAEI,qBAAsB,CAGtB,eAAgB,CAChB,sBAAuB,CACvB,iBACJ,CAEA,qCAPI,kBAAmB,CAFnB,YAAa,CAGb,sBAkBJ,CAZA,qBAUI,yCAA0C,CAF1C,2CAA4C,CAC5C,mBAAoB,CAEpB,yBAA0B,CAP1B,aAAc,CAEd,WAAY,CACZ,4BAA6B,CAF7B,UAOJ,CAEI,yBACI,aACJ,CAEJ,sBAKI,+BAAgC,CAHhC,6BAA8B,CAC9B,mCAAoC,CACpC,eAAgB,CAHhB,4BAKJ,CAEA,wBAKI,iCAAkC,CAFlC,6BAA8B,CAC9B,sCAAuC,CAFvC,4BAA6B,CAD7B,eAKJ,CAEA,oBAEI,kBAAmB,CAKnB,oCAAqC,CAFrC,WAAY,CACZ,8BAA+B,CAE/B,+BAAgC,CAGhC,cAAe,CAVf,mBAAoB,CAQpB,+BAAgC,CAChC,uCAAwC,CAPxC,kBAAmB,CACnB,qCAAsC,CAQtC,mFACJ,CAEI,0BACI,0CACJ,CAEA,2BACI,oBACJ,CAEA,kCACI,qCAAsC,CACtC,kBACJ,CAEJ,wBAMI,sCAAuC,CADvC,8BAA+B,CAF/B,yBAA0B,CAD1B,eAAgB,CAEhB,sBAAuB,CAGvB,eAAgB,CANhB,UAOJ,CAEI,gCAGI,gCAAiC,CAFjC,cAAe,CACf,6BAEJ,CAEA,4BAOI,yBAA0B,CAH1B,mCAAoC,CACpC,6BAA8B,CAC9B,eAAgB,CALhB,yBAA0B,CAC1B,gBAAiB,CACjB,eAAgB,CAKhB,oBAAqB,CACrB,qBACJ,CAEJ,uCACI,oBACI,yBACJ,CACJ","sources":["styles/tokens.css","styles/animations.css","styles/theme-dark.css","styles/theme-midnight.css","index.css","App.css","components/CategoryDot.css","components/CategoryBadge.css","components/ReceiptItem.css","components/ReceiptItemList.css","components/ReceiptTotal.css","components/EmptyState.css","components/ConfirmDialog.css","components/VoiceIndicator.css","components/SaveAnimation.css","components/CategoryReviewPrompt.css","pages/NewReceipt.css","pages/ReceiptHistory.css","pages/ReceiptDetails.css","components/PeriodSelector.css","components/CategoryBar.css","pages/Statistics.css","components/StorageIndicator.css","components/ThemeSelector.css","pages/SettingsPage.css","components/NavigationBar.css","components/Notification.css","components/CategoryDebugPanel.css","components/ErrorBoundary.css"],"sourcesContent":["/* src/styles/tokens.css */\r\n/* ============================================\r\n   CheckVoice � ������-������\r\n   �������: �Ҹ���� ��������� (Warm Receipt)\r\n   ============================================ */\r\n\r\n:root {\r\n    /* ----------------------------------------\r\n     �����: ������\r\n     ---------------------------------------- */\r\n    /* ���� */\r\n    --color-bg-primary: #FAF7F2; /* �������� ��� � ����� �������� */\r\n    --color-bg-secondary: #F3EDE4; /* ��������� ��� � ���� ������ */\r\n    --color-bg-surface: #FFFFFF; /* ����������� �������� */\r\n    --color-bg-surface-hover: #F9F6F1; /* �������� ��� hover */\r\n    --color-bg-elevated: #FFFFFF; /* ����������� ������� (�������, nav) */\r\n    --color-bg-inset: #F0EBE3; /* ���������� ������� (������, ���������) */\r\n    /* ����� */\r\n    --color-text-primary: #2C2520; /* �������� ����� � ����� ������ */\r\n    --color-text-secondary: #78706A; /* ��������� ����� */\r\n    --color-text-tertiary: #A49E98; /* ��������� (���������, ����) */\r\n    --color-text-placeholder: #C4BEB8; /* Placeholder � ������� */\r\n    --color-text-inverse: #FFFFFF; /* ����� �� �����/������� ���� */\r\n    /* ������ � ����-������ (��������) */\r\n    --color-accent: #21A038; /* �������� ������ � ���������� ������ */\r\n    --color-accent-hover: #1B8A2F; /* Hover */\r\n    --color-accent-active: #167826; /* Active/Pressed */\r\n    --color-accent-soft: rgba(33, 160, 56, 0.10); /* ������ ��� */\r\n    --color-accent-medium: rgba(33, 160, 56, 0.18); /* ������� ��� */\r\n    /* ��������� ������ � ����� �������� */\r\n    --color-secondary: #D4862A; /* �������� ��� ��������� �������� */\r\n    --color-secondary-soft: rgba(212, 134, 42, 0.10);\r\n    --color-secondary-medium: rgba(212, 134, 42, 0.18);\r\n    /* ������������� */\r\n    --color-danger: #C0392B; /* ��������, ������ */\r\n    --color-danger-hover: #A93226;\r\n    --color-danger-soft: rgba(192, 57, 43, 0.08);\r\n    --color-danger-medium: rgba(192, 57, 43, 0.15);\r\n    /* ����� */\r\n    --color-success: #27AE60;\r\n    --color-success-soft: rgba(39, 174, 96, 0.10);\r\n    /* �������������� */\r\n    --color-warning: #E67E22;\r\n    --color-warning-soft: rgba(230, 126, 34, 0.10);\r\n    /* ������� � ����������� */\r\n    --color-border: rgba(44, 37, 32, 0.10); /* ������� ������� */\r\n    --color-border-hover: rgba(44, 37, 32, 0.18); /* ������� ��� hover */\r\n    --color-border-focus: var(--color-accent); /* ������� ��� ������ */\r\n    --color-border-dashed: rgba(44, 37, 32, 0.20); /* ���������� ����������� */\r\n    /* ���� */\r\n    --shadow-xs: 0 1px 2px rgba(44, 37, 32, 0.05);\r\n    --shadow-sm: 0 1px 3px rgba(44, 37, 32, 0.08), 0 1px 2px rgba(44, 37, 32, 0.04);\r\n    --shadow-md: 0 4px 12px rgba(44, 37, 32, 0.08), 0 2px 4px rgba(44, 37, 32, 0.04);\r\n    --shadow-lg: 0 8px 24px rgba(44, 37, 32, 0.10), 0 4px 8px rgba(44, 37, 32, 0.05);\r\n    --shadow-xl: 0 16px 48px rgba(44, 37, 32, 0.12), 0 8px 16px rgba(44, 37, 32, 0.06);\r\n    --shadow-dialog: 0 20px 60px rgba(44, 37, 32, 0.15), 0 8px 20px rgba(44, 37, 32, 0.08);\r\n    /* ������� */\r\n    --color-overlay: rgba(44, 37, 32, 0.45);\r\n    /* ----------------------------------------\r\n     �����������\r\n     ---------------------------------------- */\r\n    --font-family-base: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;\r\n    --font-family-mono: 'JetBrains Mono', 'SF Mono', 'Fira Code', 'Consolas', monospace;\r\n    /* ������� ������� */\r\n    --font-size-xs: 11px;\r\n    --font-size-sm: 13px;\r\n    --font-size-base: 15px;\r\n    --font-size-md: 16px;\r\n    --font-size-lg: 18px;\r\n    --font-size-xl: 22px;\r\n    --font-size-2xl: 28px;\r\n    --font-size-3xl: 36px;\r\n    /* ����������� �������� */\r\n    --line-height-tight: 1.2;\r\n    --line-height-base: 1.5;\r\n    --line-height-relaxed: 1.6;\r\n    /* ������� ������� */\r\n    --font-weight-normal: 400;\r\n    --font-weight-medium: 500;\r\n    --font-weight-semibold: 600;\r\n    --font-weight-bold: 700;\r\n    /* ������������ */\r\n    --letter-spacing-tight: -0.01em;\r\n    --letter-spacing-normal: 0;\r\n    --letter-spacing-wide: 0.02em;\r\n    --letter-spacing-caps: 0.06em;\r\n    /* ----------------------------------------\r\n     ����������\r\n     ---------------------------------------- */\r\n    --radius-xs: 4px;\r\n    --radius-sm: 8px;\r\n    --radius-md: 12px;\r\n    --radius-lg: 16px;\r\n    --radius-xl: 20px;\r\n    --radius-2xl: 24px;\r\n    --radius-pill: 9999px;\r\n    /* ----------------------------------------\r\n     ������� (4px ����)\r\n     ---------------------------------------- */\r\n    --space-1: 4px;\r\n    --space-2: 8px;\r\n    --space-3: 12px;\r\n    --space-4: 16px;\r\n    --space-5: 20px;\r\n    --space-6: 24px;\r\n    --space-7: 28px;\r\n    --space-8: 32px;\r\n    --space-9: 36px;\r\n    --space-10: 40px;\r\n    --space-12: 48px;\r\n    --space-16: 64px;\r\n    /* ----------------------------------------\r\n     ������� �����������\r\n     ---------------------------------------- */\r\n    --nav-height: 56px;\r\n    --content-max-width: 640px;\r\n    --input-height: 48px;\r\n    --btn-height: 48px;\r\n    --btn-height-sm: 36px;\r\n    /* ----------------------------------------\r\n     ��������\r\n     ---------------------------------------- */\r\n    --transition-fast: 120ms ease-out;\r\n    --transition-base: 200ms ease-out;\r\n    --transition-slow: 300ms ease-out;\r\n    --transition-spring: 400ms cubic-bezier(0.34, 1.56, 0.64, 1);\r\n    /* ----------------------------------------\r\n     ��������� �������\r\n     ������������ ��� ����� �������:\r\n     ������������, �� ���������� �� ������� ����\r\n     ---------------------------------------- */\r\n    --cat-fish: #2E8B8B; /* ��������� ������������ */\r\n    --cat-fish-soft: rgba(46, 139, 139, 0.12);\r\n    --cat-dairy: #4A8DB7; /* ��������� ������� */\r\n    --cat-dairy-soft: rgba(74, 141, 183, 0.12);\r\n    --cat-deli: #C4603A; /* ������������ */\r\n    --cat-deli-soft: rgba(196, 96, 58, 0.12);\r\n    --cat-meat: #B84A4A; /* ������������ ������� */\r\n    --cat-meat-soft: rgba(184, 74, 74, 0.12);\r\n    --cat-spices: #B8962E; /* ��������� */\r\n    --cat-spices-soft: rgba(184, 150, 46, 0.12);\r\n    --cat-bread: #C48840; /* ������� */\r\n    --cat-bread-soft: rgba(196, 136, 64, 0.12);\r\n    --cat-fruits: #5A9E5A; /* ������ ������ */\r\n    --cat-fruits-soft: rgba(90, 158, 90, 0.12);\r\n    --cat-vegetables: #6B9E3A; /* �������� */\r\n    --cat-vegetables-soft: rgba(107, 158, 58, 0.12);\r\n    --cat-cereals: #9E923A; /* ��������� */\r\n    --cat-cereals-soft: rgba(158, 146, 58, 0.12);\r\n    --cat-canned: #C47040; /* ���������� ��������� */\r\n    --cat-canned-soft: rgba(196, 112, 64, 0.12);\r\n    --cat-frozen: #5A8EB8; /* ������� ������� */\r\n    --cat-frozen-soft: rgba(90, 142, 184, 0.12);\r\n    --cat-drinks-nonalc: #8A6AAE; /* ���������� */\r\n    --cat-drinks-nonalc-soft: rgba(138, 106, 174, 0.12);\r\n    --cat-drinks-alc: #6B4E9E; /* ����������� */\r\n    --cat-drinks-alc-soft: rgba(107, 78, 158, 0.12);\r\n    --cat-sweets: #C46A8A; /* ������� ����� */\r\n    --cat-sweets-soft: rgba(196, 106, 138, 0.12);\r\n    --cat-baby: #D4A840; /* ��������� */\r\n    --cat-baby-soft: rgba(212, 168, 64, 0.12);\r\n    --cat-pets: #8B7260; /* ��������� */\r\n    --cat-pets-soft: rgba(139, 114, 96, 0.12);\r\n    --cat-household: #8A7E72; /* �������� */\r\n    --cat-household-soft: rgba(138, 126, 114, 0.12);\r\n    --cat-hygiene: #4A9EA8; /* ������ ��������� */\r\n    --cat-hygiene-soft: rgba(74, 158, 168, 0.12);\r\n    --cat-other: #9E9A94; /* ����������� */\r\n    --cat-other-soft: rgba(158, 154, 148, 0.12);\r\n    --assistant-panel-height: 76px;\r\n}\r\n","/* src/styles/animations.css */\r\n/* ============================================\r\n   CheckVoice � �������� � ��������\r\n   ============================================ */\r\n\r\n/* ----------------------------------------\r\n   ��������� ���������\r\n   ---------------------------------------- */\r\n\r\n@keyframes cv-fade-in {\r\n    from {\r\n        opacity: 0;\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n    }\r\n}\r\n\r\n@keyframes cv-fade-in-up {\r\n    from {\r\n        opacity: 0;\r\n        transform: translateY(8px);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: translateY(0);\r\n    }\r\n}\r\n\r\n@keyframes cv-fade-in-down {\r\n    from {\r\n        opacity: 0;\r\n        transform: translateY(-8px);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: translateY(0);\r\n    }\r\n}\r\n\r\n@keyframes cv-slide-in-up {\r\n    from {\r\n        opacity: 0;\r\n        transform: translateY(16px);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: translateY(0);\r\n    }\r\n}\r\n\r\n@keyframes cv-scale-in {\r\n    from {\r\n        opacity: 0;\r\n        transform: scale(0.95);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: scale(1);\r\n    }\r\n}\r\n\r\n/* ----------------------------------------\r\n   �����������\r\n   ---------------------------------------- */\r\n\r\n@keyframes cv-toast-in {\r\n    from {\r\n        opacity: 0;\r\n        transform: translateX(-50%) translateY(-16px) scale(0.96);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: translateX(-50%) translateY(0) scale(1);\r\n    }\r\n}\r\n\r\n@keyframes cv-toast-out {\r\n    from {\r\n        opacity: 1;\r\n        transform: translateX(-50%) translateY(0) scale(1);\r\n    }\r\n\r\n    to {\r\n        opacity: 0;\r\n        transform: translateX(-50%) translateY(-16px) scale(0.96);\r\n    }\r\n}\r\n\r\n/* ----------------------------------------\r\n   �������\r\n   ---------------------------------------- */\r\n\r\n@keyframes cv-overlay-in {\r\n    from {\r\n        opacity: 0;\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n    }\r\n}\r\n\r\n@keyframes cv-dialog-in {\r\n    from {\r\n        opacity: 0;\r\n        transform: scale(0.94) translateY(8px);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: scale(1) translateY(0);\r\n    }\r\n}\r\n\r\n/* ----------------------------------------\r\n   �������� ������\r\n   ---------------------------------------- */\r\n\r\n@keyframes cv-item-in {\r\n    from {\r\n        opacity: 0;\r\n        transform: translateX(-12px);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: translateX(0);\r\n    }\r\n}\r\n\r\n@keyframes cv-item-remove {\r\n    to {\r\n        opacity: 0;\r\n        transform: translateX(24px);\r\n        max-height: 0;\r\n        margin-bottom: 0;\r\n        padding-top: 0;\r\n        padding-bottom: 0;\r\n    }\r\n}\r\n\r\n/* ----------------------------------------\r\n   �������� ��������\r\n   ---------------------------------------- */\r\n\r\n@keyframes cv-number-up {\r\n    from {\r\n        opacity: 0;\r\n        transform: translateY(100%);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: translateY(0);\r\n    }\r\n}\r\n\r\n@keyframes cv-number-bump {\r\n    0% {\r\n        transform: scale(1);\r\n    }\r\n\r\n    40% {\r\n        transform: scale(1.06);\r\n    }\r\n\r\n    100% {\r\n        transform: scale(1);\r\n    }\r\n}\r\n\r\n/* ----------------------------------------\r\n   ��������� (��������� ����, ��������)\r\n   ---------------------------------------- */\r\n\r\n@keyframes cv-pulse {\r\n    0%, 100% {\r\n        opacity: 1;\r\n    }\r\n\r\n    50% {\r\n        opacity: 0.5;\r\n    }\r\n}\r\n\r\n@keyframes cv-pulse-ring {\r\n    0% {\r\n        transform: scale(0.8);\r\n        opacity: 0.6;\r\n    }\r\n\r\n    100% {\r\n        transform: scale(1.8);\r\n        opacity: 0;\r\n    }\r\n}\r\n\r\n/* ----------------------------------------\r\n   ��������� ��������� (toast auto-close)\r\n   ---------------------------------------- */\r\n\r\n@keyframes cv-progress-shrink {\r\n    from {\r\n        transform: scaleX(1);\r\n    }\r\n\r\n    to {\r\n        transform: scaleX(0);\r\n    }\r\n}\r\n\r\n/* ----------------------------------------\r\n   ����������� ������ ��������\r\n   ---------------------------------------- */\r\n\r\n.cv-animate-fade-in {\r\n    animation: cv-fade-in var(--transition-base) both;\r\n}\r\n\r\n.cv-animate-fade-in-up {\r\n    animation: cv-fade-in-up var(--transition-slow) both;\r\n}\r\n\r\n.cv-animate-slide-in-up {\r\n    animation: cv-slide-in-up var(--transition-slow) both;\r\n}\r\n\r\n.cv-animate-scale-in {\r\n    animation: cv-scale-in var(--transition-base) both;\r\n}\r\n\r\n/* �������� ��� ���������� ��������� */\r\n.cv-delay-1 {\r\n    animation-delay: 50ms;\r\n}\r\n\r\n.cv-delay-2 {\r\n    animation-delay: 100ms;\r\n}\r\n\r\n.cv-delay-3 {\r\n    animation-delay: 150ms;\r\n}\r\n\r\n.cv-delay-4 {\r\n    animation-delay: 200ms;\r\n}\r\n\r\n.cv-delay-5 {\r\n    animation-delay: 250ms;\r\n}\r\n\r\n/* ----------------------------------------\r\n   Respect user preferences\r\n   ---------------------------------------- */\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    *,\r\n    *::before,\r\n    *::after {\r\n        animation-duration: 0.01ms !important;\r\n        animation-iteration-count: 1 !important;\r\n        transition-duration: 0.01ms !important;\r\n    }\r\n}\r\n","/* src/styles/theme-dark.css */\r\n/* ============================================\r\n   CheckVoice � Ҹ���� ���� ��������� �������\r\n   ������������ ����� data-theme=\"dark\" �� <html>\r\n   ============================================ */\r\n\r\n[data-theme=\"dark\"] {\r\n    /* ���� */\r\n    --color-bg-primary: #0A1A14;\r\n    --color-bg-secondary: #0E2018;\r\n    --color-bg-surface: #14302A;\r\n    --color-bg-surface-hover: #193830;\r\n    --color-bg-elevated: #1A3A32;\r\n    --color-bg-inset: #0D1E16;\r\n    /* ����� */\r\n    --color-text-primary: #E8F0EC;\r\n    --color-text-secondary: #A0B8AC;\r\n    --color-text-tertiary: #6E8C7C;\r\n    --color-text-placeholder: #4A6E5A;\r\n    --color-text-inverse: #0A1A14;\r\n    /* ������ */\r\n    --color-accent: #4ADE80;\r\n    --color-accent-hover: #6EE7A0;\r\n    --color-accent-active: #86EFAC;\r\n    --color-accent-soft: rgba(74, 222, 128, 0.12);\r\n    --color-accent-medium: rgba(74, 222, 128, 0.20);\r\n    /* ��������� */\r\n    --color-secondary: #FBBF24;\r\n    --color-secondary-soft: rgba(251, 191, 36, 0.12);\r\n    --color-secondary-medium: rgba(251, 191, 36, 0.20);\r\n    /* ������������� */\r\n    --color-danger: #F87171;\r\n    --color-danger-hover: #FCA5A5;\r\n    --color-danger-soft: rgba(248, 113, 113, 0.10);\r\n    --color-danger-medium: rgba(248, 113, 113, 0.18);\r\n    /* ����� / �������������� */\r\n    --color-success: #4ADE80;\r\n    --color-success-soft: rgba(74, 222, 128, 0.12);\r\n    --color-warning: #FBBF24;\r\n    --color-warning-soft: rgba(251, 191, 36, 0.12);\r\n    /* ������� */\r\n    --color-border: rgba(232, 240, 236, 0.10);\r\n    --color-border-hover: rgba(232, 240, 236, 0.18);\r\n    --color-border-dashed: rgba(232, 240, 236, 0.15);\r\n    /* ���� (�� ����� ���� � ������) */\r\n    --shadow-xs: 0 1px 2px rgba(0, 0, 0, 0.20);\r\n    --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.25), 0 1px 2px rgba(0, 0, 0, 0.15);\r\n    --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.30), 0 2px 4px rgba(0, 0, 0, 0.15);\r\n    --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.35), 0 4px 8px rgba(0, 0, 0, 0.20);\r\n    --shadow-xl: 0 16px 48px rgba(0, 0, 0, 0.40), 0 8px 16px rgba(0, 0, 0, 0.25);\r\n    --shadow-dialog: 0 20px 60px rgba(0, 0, 0, 0.50), 0 8px 20px rgba(0, 0, 0, 0.30);\r\n    /* ������� */\r\n    --color-overlay: rgba(0, 0, 0, 0.55);\r\n    /* ��������� (���� �� ����� ����) */\r\n    --cat-fish: #4DB8B8;\r\n    --cat-fish-soft: rgba(77, 184, 184, 0.15);\r\n    --cat-dairy: #5EAAD4;\r\n    --cat-dairy-soft: rgba(94, 170, 212, 0.15);\r\n    --cat-deli: #E07850;\r\n    --cat-deli-soft: rgba(224, 120, 80, 0.15);\r\n    --cat-meat: #D46060;\r\n    --cat-meat-soft: rgba(212, 96, 96, 0.15);\r\n    --cat-spices: #D4B240;\r\n    --cat-spices-soft: rgba(212, 178, 64, 0.15);\r\n    --cat-bread: #D4A050;\r\n    --cat-bread-soft: rgba(212, 160, 80, 0.15);\r\n    --cat-fruits: #6EBA6E;\r\n    --cat-fruits-soft: rgba(110, 186, 110, 0.15);\r\n    --cat-vegetables: #82B84E;\r\n    --cat-vegetables-soft: rgba(130, 184, 78, 0.15);\r\n    --cat-cereals: #B8AC4E;\r\n    --cat-cereals-soft: rgba(184, 172, 78, 0.15);\r\n    --cat-canned: #D48850;\r\n    --cat-canned-soft: rgba(212, 136, 80, 0.15);\r\n    --cat-frozen: #6EA8D4;\r\n    --cat-frozen-soft: rgba(110, 168, 212, 0.15);\r\n    --cat-drinks-nonalc: #A882CC;\r\n    --cat-drinks-nonalc-soft: rgba(168, 130, 204, 0.15);\r\n    --cat-drinks-alc: #8468BA;\r\n    --cat-drinks-alc-soft: rgba(132, 104, 186, 0.15);\r\n    --cat-sweets: #D482A0;\r\n    --cat-sweets-soft: rgba(212, 130, 160, 0.15);\r\n    --cat-baby: #E4C050;\r\n    --cat-baby-soft: rgba(228, 192, 80, 0.15);\r\n    --cat-pets: #A89080;\r\n    --cat-pets-soft: rgba(168, 144, 128, 0.15);\r\n    --cat-household: #A89888;\r\n    --cat-household-soft: rgba(168, 152, 136, 0.15);\r\n    --cat-hygiene: #5EB8C4;\r\n    --cat-hygiene-soft: rgba(94, 184, 196, 0.15);\r\n    --cat-other: #B8B4AE;\r\n    --cat-other-soft: rgba(184, 180, 174, 0.15);\r\n}\r\n\r\n    /* ��� body ��� ����� ���� */\r\n    [data-theme=\"dark\"] body {\r\n        background-image: radial-gradient(ellipse at 20% 0%, rgba(74, 222, 128, 0.04) 0%, transparent 60%), radial-gradient(ellipse at 80% 100%, rgba(251, 191, 36, 0.03) 0%, transparent 60%);\r\n    }\r\n\r\n    /* ������ � �������������� ����� */\r\n    [data-theme=\"dark\"] .navigation-bar {\r\n        background-color: rgba(10, 26, 20, 0.90);\r\n    }\r\n","/* src/styles/theme-midnight.css */\r\n/* ============================================\r\n   CheckVoice � ���� ��������� (����-�����)\r\n   ������������ ����� data-theme=\"midnight\" �� <html>\r\n   ============================================ */\r\n\r\n[data-theme=\"midnight\"] {\r\n\t--color-bg-primary: #0F172A;\r\n\t--color-bg-secondary: #141D32;\r\n\t--color-bg-surface: #1E293B;\r\n\t--color-bg-surface-hover: #253348;\r\n\t--color-bg-elevated: #1E293B;\r\n\t--color-bg-inset: #0C1322;\r\n\t--color-text-primary: #F1F5F9;\r\n\t--color-text-secondary: #94A3B8;\r\n\t--color-text-tertiary: #64748B;\r\n\t--color-text-placeholder: #475569;\r\n\t--color-text-inverse: #0F172A;\r\n\t--color-accent: #38BDF8;\r\n\t--color-accent-hover: #7DD3FC;\r\n\t--color-accent-active: #BAE6FD;\r\n\t--color-accent-soft: rgba(56, 189, 248, 0.12);\r\n\t--color-accent-medium: rgba(56, 189, 248, 0.20);\r\n\t--color-secondary: #A78BFA;\r\n\t--color-secondary-soft: rgba(167, 139, 250, 0.12);\r\n\t--color-secondary-medium: rgba(167, 139, 250, 0.20);\r\n\t--color-danger: #FB7185;\r\n\t--color-danger-hover: #FDA4AF;\r\n\t--color-danger-soft: rgba(251, 113, 133, 0.10);\r\n\t--color-danger-medium: rgba(251, 113, 133, 0.18);\r\n\t--color-success: #4ADE80;\r\n\t--color-success-soft: rgba(74, 222, 128, 0.12);\r\n\t--color-warning: #FBBF24;\r\n\t--color-warning-soft: rgba(251, 191, 36, 0.12);\r\n\t--color-border: rgba(241, 245, 249, 0.08);\r\n\t--color-border-hover: rgba(241, 245, 249, 0.15);\r\n\t--color-border-dashed: rgba(241, 245, 249, 0.12);\r\n\t--shadow-xs: 0 1px 2px rgba(0, 0, 0, 0.25);\r\n\t--shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.30), 0 1px 2px rgba(0, 0, 0, 0.20);\r\n\t--shadow-md: 0 4px 12px rgba(0, 0, 0, 0.35), 0 2px 4px rgba(0, 0, 0, 0.20);\r\n\t--shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.40), 0 4px 8px rgba(0, 0, 0, 0.25);\r\n\t--shadow-xl: 0 16px 48px rgba(0, 0, 0, 0.45), 0 8px 16px rgba(0, 0, 0, 0.30);\r\n\t--shadow-dialog: 0 20px 60px rgba(0, 0, 0, 0.55), 0 8px 20px rgba(0, 0, 0, 0.35);\r\n\t--color-overlay: rgba(0, 0, 0, 0.60);\r\n\t/* ��������� (����� �� �����) */\r\n\t--cat-fish: #2DD4BF;\r\n\t--cat-fish-soft: rgba(45, 212, 191, 0.15);\r\n\t--cat-dairy: #7DD3FC;\r\n\t--cat-dairy-soft: rgba(125, 211, 252, 0.15);\r\n\t--cat-deli: #FB923C;\r\n\t--cat-deli-soft: rgba(251, 146, 60, 0.15);\r\n\t--cat-meat: #F87171;\r\n\t--cat-meat-soft: rgba(248, 113, 113, 0.15);\r\n\t--cat-spices: #FDE047;\r\n\t--cat-spices-soft: rgba(253, 224, 71, 0.15);\r\n\t--cat-bread: #FBBF24;\r\n\t--cat-bread-soft: rgba(251, 191, 36, 0.15);\r\n\t--cat-fruits: #4ADE80;\r\n\t--cat-fruits-soft: rgba(74, 222, 128, 0.15);\r\n\t--cat-vegetables: #86EFAC;\r\n\t--cat-vegetables-soft: rgba(134, 239, 172, 0.15);\r\n\t--cat-cereals: #BEF264;\r\n\t--cat-cereals-soft: rgba(190, 242, 100, 0.15);\r\n\t--cat-canned: #FB923C;\r\n\t--cat-canned-soft: rgba(251, 146, 60, 0.15);\r\n\t--cat-frozen: #7DD3FC;\r\n\t--cat-frozen-soft: rgba(125, 211, 252, 0.15);\r\n\t--cat-drinks-nonalc: #C4B5FD;\r\n\t--cat-drinks-nonalc-soft: rgba(196, 181, 253, 0.15);\r\n\t--cat-drinks-alc: #A78BFA;\r\n\t--cat-drinks-alc-soft: rgba(167, 139, 250, 0.15);\r\n\t--cat-sweets: #FDA4AF;\r\n\t--cat-sweets-soft: rgba(253, 164, 175, 0.15);\r\n\t--cat-baby: #FDE047;\r\n\t--cat-baby-soft: rgba(253, 224, 71, 0.15);\r\n\t--cat-pets: #D6D3D1;\r\n\t--cat-pets-soft: rgba(214, 211, 209, 0.15);\r\n\t--cat-household: #A8A29E;\r\n\t--cat-household-soft: rgba(168, 162, 158, 0.15);\r\n\t--cat-hygiene: #67E8F9;\r\n\t--cat-hygiene-soft: rgba(103, 232, 249, 0.15);\r\n\t--cat-other: #CBD5E1;\r\n\t--cat-other-soft: rgba(203, 213, 225, 0.15);\r\n}\r\n\r\n\t[data-theme=\"midnight\"] body {\r\n\t\tbackground-image: radial-gradient(ellipse at 20% 0%, rgba(56, 189, 248, 0.04) 0%, transparent 60%), radial-gradient(ellipse at 80% 100%, rgba(167, 139, 250, 0.03) 0%, transparent 60%);\r\n\t}\r\n\r\n\t[data-theme=\"midnight\"] .navigation-bar {\r\n\t\tbackground-color: rgba(15, 23, 42, 0.90);\r\n\t}\r\n","/* src/index.css */\r\n/* ============================================\r\n   CheckVoice — Базовые глобальные стили\r\n   ============================================ */\r\n\r\n@import './styles/tokens.css';\r\n@import './styles/animations.css';\r\n@import './styles/theme-dark.css';\r\n@import './styles/theme-midnight.css';\r\n\r\n/* ----------------------------------------\r\n   Подключение шрифтов\r\n   ---------------------------------------- */\r\n\r\n/* Inter — основной */\r\n@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');\r\n\r\n/* JetBrains Mono — для цен и чековой стилистики */\r\n@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@500;700&display=swap');\r\n\r\n/* ----------------------------------------\r\n   Reset & Base\r\n   ---------------------------------------- */\r\n\r\n*,\r\n*::before,\r\n*::after {\r\n    box-sizing: border-box;\r\n    margin: 0;\r\n    padding: 0;\r\n}\r\n\r\nhtml {\r\n    /* Плавный скролл */\r\n    scroll-behavior: smooth;\r\n    /* Предотвращаем масштабирование на iOS при фокусе в инпут */\r\n    -webkit-text-size-adjust: 100%;\r\n}\r\n\r\nbody {\r\n    font-family: var(--font-family-base);\r\n    font-size: var(--font-size-base);\r\n    line-height: var(--line-height-base);\r\n    font-weight: var(--font-weight-normal);\r\n    color: var(--color-text-primary);\r\n    background-color: var(--color-bg-primary);\r\n    -webkit-font-smoothing: antialiased;\r\n    -moz-osx-font-smoothing: grayscale;\r\n    overflow-x: hidden;\r\n    /* Тёплая текстура фона — едва заметный noise-эффект через градиент */\r\n    background-image: radial-gradient(ellipse at 20% 0%, rgba(33, 160, 56, 0.03) 0%, transparent 60%), radial-gradient(ellipse at 80% 100%, rgba(212, 134, 42, 0.03) 0%, transparent 60%);\r\n    background-attachment: fixed;\r\n    min-height: 100vh;\r\n}\r\n\r\n/* ----------------------------------------\r\n   Типографика — базовые элементы\r\n   ---------------------------------------- */\r\n\r\nh1, h2, h3, h4 {\r\n    font-weight: var(--font-weight-bold);\r\n    line-height: var(--line-height-tight);\r\n    letter-spacing: var(--letter-spacing-tight);\r\n    color: var(--color-text-primary);\r\n}\r\n\r\np {\r\n    line-height: var(--line-height-relaxed);\r\n    color: var(--color-text-secondary);\r\n}\r\n\r\n/* ----------------------------------------\r\n   Формы — базовые элементы\r\n   ---------------------------------------- */\r\n\r\ninput,\r\nbutton,\r\nselect,\r\ntextarea {\r\n    font-family: inherit;\r\n    font-size: inherit;\r\n    line-height: inherit;\r\n}\r\n\r\n    input::placeholder {\r\n        color: var(--color-text-placeholder);\r\n    }\r\n\r\nbutton {\r\n    cursor: pointer;\r\n    border: none;\r\n    background: none;\r\n    color: inherit;\r\n}\r\n\r\n/* ----------------------------------------\r\n   Списки\r\n   ---------------------------------------- */\r\n\r\nul, ol {\r\n    list-style: none;\r\n}\r\n\r\n/* ----------------------------------------\r\n   Скроллбар (webkit)\r\n   ---------------------------------------- */\r\n\r\n::-webkit-scrollbar {\r\n    width: 5px;\r\n}\r\n\r\n::-webkit-scrollbar-track {\r\n    background: transparent;\r\n}\r\n\r\n::-webkit-scrollbar-thumb {\r\n    background-color: var(--color-border);\r\n    border-radius: var(--radius-pill);\r\n}\r\n\r\n    ::-webkit-scrollbar-thumb:hover {\r\n        background-color: var(--color-border-hover);\r\n    }\r\n\r\n/* Firefox */\r\n* {\r\n    scrollbar-width: thin;\r\n    scrollbar-color: var(--color-border) transparent;\r\n}\r\n\r\n/* ----------------------------------------\r\n   Убираем стрелки у числовых инпутов\r\n   ---------------------------------------- */\r\n\r\ninput[type=number]::-webkit-outer-spin-button,\r\ninput[type=number]::-webkit-inner-spin-button {\r\n    -webkit-appearance: none;\r\n    margin: 0;\r\n}\r\n\r\ninput[type=number] {\r\n    -moz-appearance: textfield;\r\n}\r\n\r\n/* ----------------------------------------\r\n   Фокус — accessibility\r\n   ---------------------------------------- */\r\n\r\n:focus-visible {\r\n    outline: 2px solid var(--color-accent);\r\n    outline-offset: 2px;\r\n    border-radius: var(--radius-xs);\r\n}\r\n\r\n/* Убираем outline для мыши, оставляем для клавиатуры */\r\n:focus:not(:focus-visible) {\r\n    outline: none;\r\n}\r\n\r\n/* ----------------------------------------\r\n   Выделение текста\r\n   ---------------------------------------- */\r\n\r\n::selection {\r\n    background-color: var(--color-accent-soft);\r\n    color: var(--color-text-primary);\r\n}\r\n","/* src/App.css */\r\n/* ============================================\r\n   CheckVoice � �������� ������\r\n   ============================================ */\r\n\r\n.app {\r\n    min-height: 100vh;\r\n    min-height: 100dvh; /* dynamic viewport height ��� ��������� */\r\n    padding-top: calc(var(--nav-height) + var(--space-2));\r\n    padding-bottom: var(--space-8);\r\n    display: flex;\r\n    flex-direction: column;\r\n}\r\n\r\n.app-content {\r\n    flex: 1;\r\n    width: 100%;\r\n    max-width: var(--content-max-width);\r\n    margin: 0 auto;\r\n    padding: var(--space-4);\r\n}\r\n\r\n/* ----------------------------------------\r\n   ����� ����� ������� (page-header)\r\n   ������������ �� ���� �������\r\n   ---------------------------------------- */\r\n\r\n.page-header {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    margin-bottom: var(--space-6);\r\n}\r\n\r\n.page-header-left {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: var(--space-3);\r\n}\r\n\r\n.page-header-icon {\r\n    color: var(--color-accent);\r\n    flex-shrink: 0;\r\n}\r\n\r\n.page-title {\r\n    font-size: var(--font-size-xl);\r\n    font-weight: var(--font-weight-bold);\r\n    color: var(--color-text-primary);\r\n    margin: 0;\r\n}\r\n\r\n.page-subtitle {\r\n    font-size: var(--font-size-sm);\r\n    color: var(--color-text-tertiary);\r\n    font-weight: var(--font-weight-medium);\r\n}\r\n\r\n/* ----------------------------------------\r\n   ����� ����� ��������\r\n   ���������������� ������� ��� ���� ������������\r\n   ---------------------------------------- */\r\n\r\n.cv-card {\r\n    background-color: var(--color-bg-surface);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-lg);\r\n    padding: var(--space-4) var(--space-5);\r\n    box-shadow: var(--shadow-xs);\r\n    transition: background-color var(--transition-fast), border-color var(--transition-fast), box-shadow var(--transition-fast);\r\n}\r\n\r\n    .cv-card:hover {\r\n        border-color: var(--color-border-hover);\r\n    }\r\n\r\n.cv-card--interactive {\r\n    cursor: pointer;\r\n}\r\n\r\n    .cv-card--interactive:hover {\r\n        box-shadow: var(--shadow-sm);\r\n        background-color: var(--color-bg-surface-hover);\r\n    }\r\n\r\n    .cv-card--interactive:active {\r\n        transform: scale(0.995);\r\n        box-shadow: var(--shadow-xs);\r\n    }\r\n\r\n/* ----------------------------------------\r\n   ����� ����� ������\r\n   ---------------------------------------- */\r\n\r\n.cv-btn {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    gap: var(--space-2);\r\n    height: var(--btn-height);\r\n    padding: 0 var(--space-6);\r\n    border: none;\r\n    border-radius: var(--radius-md);\r\n    font-size: var(--font-size-base);\r\n    font-weight: var(--font-weight-semibold);\r\n    cursor: pointer;\r\n    transition: all var(--transition-fast);\r\n    user-select: none;\r\n    white-space: nowrap;\r\n}\r\n\r\n    .cv-btn:active {\r\n        transform: scale(0.97);\r\n    }\r\n\r\n/* ��������� (������) */\r\n.cv-btn--primary {\r\n    background-color: var(--color-accent);\r\n    color: var(--color-text-inverse);\r\n}\r\n\r\n    .cv-btn--primary:hover {\r\n        background-color: var(--color-accent-hover);\r\n    }\r\n\r\n/* ��������� (����������) */\r\n.cv-btn--secondary {\r\n    background-color: var(--color-bg-inset);\r\n    color: var(--color-text-primary);\r\n}\r\n\r\n    .cv-btn--secondary:hover {\r\n        background-color: var(--color-border);\r\n    }\r\n\r\n/* ������������� */\r\n.cv-btn--danger {\r\n    background-color: var(--color-danger-soft);\r\n    color: var(--color-danger);\r\n}\r\n\r\n    .cv-btn--danger:hover {\r\n        background-color: var(--color-danger-medium);\r\n    }\r\n\r\n/* Ghost (������ �����) */\r\n.cv-btn--ghost {\r\n    background: none;\r\n    color: var(--color-text-secondary);\r\n}\r\n\r\n    .cv-btn--ghost:hover {\r\n        background-color: var(--color-bg-inset);\r\n        color: var(--color-text-primary);\r\n    }\r\n\r\n/* ������ ������ */\r\n.cv-btn--full {\r\n    width: 100%;\r\n}\r\n\r\n/* ----------------------------------------\r\n   ������������\r\n   ---------------------------------------- */\r\n\r\n@media (min-width: 768px) {\r\n    .app-content {\r\n        padding: var(--space-6);\r\n    }\r\n}\r\n\r\n@media (min-width: 1024px) {\r\n    .app-content {\r\n        padding: var(--space-8);\r\n        max-width: 720px;\r\n    }\r\n}\r\n\r\n@media (max-width: 480px) {\r\n    .page-header {\r\n        flex-direction: column;\r\n        align-items: flex-start;\r\n        gap: var(--space-1);\r\n    }\r\n\r\n    .page-title {\r\n        font-size: var(--font-size-lg);\r\n    }\r\n}\r\n","/* src/components/CategoryDot.css */\r\n\r\n.category-dot {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    flex-shrink: 0;\r\n    border: 1px solid transparent;\r\n    border-radius: 999px;\r\n    line-height: 0;\r\n    transition: transform var(--transition-fast), background-color var(--transition-fast), border-color var(--transition-fast);\r\n}\r\n\r\n.category-dot-core {\r\n    width: 42%;\r\n    height: 42%;\r\n    border-radius: 999px;\r\n    transition: background-color var(--transition-fast);\r\n}\r\n","/* src/components/CategoryBadge.css */\r\n\r\n.category-badge {\r\n    --category-badge-color: var(--color-text-primary);\r\n    --category-badge-bg: var(--color-bg-secondary);\r\n    display: inline-flex;\r\n    align-items: center;\r\n    vertical-align: middle;\r\n    gap: var(--space-2);\r\n    min-height: 24px;\r\n    padding: var(--space-1) var(--space-3) var(--space-1) var(--space-1);\r\n    border-radius: var(--radius-pill);\r\n    background-color: var(--category-badge-bg);\r\n    color: var(--category-badge-color);\r\n    font-size: var(--font-size-xs);\r\n    font-weight: var(--font-weight-semibold);\r\n    line-height: 1;\r\n    letter-spacing: var(--letter-spacing-wide);\r\n    white-space: nowrap;\r\n    transition: background-color var(--transition-fast), color var(--transition-fast), transform var(--transition-fast);\r\n}\r\n\r\n.category-badge-name {\r\n    display: inline-block;\r\n}\r\n\r\n/* ��������� ������������ ��������� ����� */\r\n.category-badge > * {\r\n    flex-shrink: 0;\r\n}\r\n\r\n.category-badge-name {\r\n    flex-shrink: 1;\r\n    min-width: 0;\r\n}\r\n","/* src/components/ReceiptItem.css */\r\n\r\n.receipt-item {\r\n    position: relative;\r\n    overflow: hidden;\r\n    border-bottom: 1px dashed var(--color-border-dashed);\r\n    touch-action: pan-y;\r\n    animation: cv-item-in 250ms ease-out both;\r\n}\r\n\r\n    .receipt-item:last-child {\r\n        border-bottom: none;\r\n    }\r\n\r\n@keyframes cv-item-in {\r\n    from {\r\n        opacity: 0;\r\n        transform: translateY(6px);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: translateY(0);\r\n    }\r\n}\r\n\r\n/* --- ������� ���� �������� --- */\r\n\r\n.receipt-item-delete-zone {\r\n    position: absolute;\r\n    top: 0;\r\n    right: 0;\r\n    bottom: 0;\r\n    width: 100%;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: flex-end;\r\n    padding-right: var(--space-6);\r\n    background-color: var(--color-danger);\r\n    color: var(--color-text-inverse);\r\n}\r\n\r\n/* --- ������� ������ --- */\r\n\r\n.receipt-item-content {\r\n    position: relative;\r\n    z-index: 1;\r\n    padding: var(--space-4) var(--space-5);\r\n    background-color: var(--color-bg-surface);\r\n    transition: transform 200ms ease-out, background-color var(--transition-fast), box-shadow var(--transition-fast);\r\n    will-change: transform;\r\n    transform: translateZ(0);\r\n    backface-visibility: hidden;\r\n}\r\n\r\n    .receipt-item-content.swiping {\r\n        transition: none;\r\n    }\r\n\r\n    .receipt-item-content.low-confidence {\r\n        box-shadow: inset 3px 0 0 var(--color-warning);\r\n    }\r\n\r\n    .receipt-item-content.learned-exact {\r\n        box-shadow: inset 3px 0 0 var(--color-accent);\r\n    }\r\n\r\n@media (hover: hover) and (pointer: fine) {\r\n    .receipt-item:not(.read-only) .receipt-item-content:hover {\r\n        background-color: var(--color-bg-surface-hover);\r\n    }\r\n}\r\n\r\n/* --- �������� ������ --- */\r\n\r\n.item-main {\r\n    display: flex;\r\n    align-items: flex-start;\r\n    justify-content: space-between;\r\n    margin-bottom: var(--space-2);\r\n}\r\n\r\n.item-info {\r\n    display: flex;\r\n    flex: 1;\r\n    min-width: 0;\r\n    gap: var(--space-2);\r\n}\r\n\r\n.item-number {\r\n    flex-shrink: 0;\r\n    min-width: 22px;\r\n    font-family: var(--font-family-mono);\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-medium);\r\n    color: var(--color-text-tertiary);\r\n}\r\n\r\n.item-title {\r\n    color: var(--color-text-primary);\r\n    font-size: var(--font-size-base);\r\n    font-weight: var(--font-weight-medium);\r\n    line-height: var(--line-height-base);\r\n    word-break: break-word;\r\n}\r\n\r\n/* --- ���� --- */\r\n\r\n.item-price-block {\r\n    flex-shrink: 0;\r\n    margin-left: var(--space-3);\r\n}\r\n\r\n.item-price {\r\n    padding: 0;\r\n    border: none;\r\n    background: none;\r\n    font-family: var(--font-family-mono);\r\n    font-size: var(--font-size-md);\r\n    font-weight: var(--font-weight-bold);\r\n    color: var(--color-text-primary);\r\n    white-space: nowrap;\r\n    line-height: 1.2;\r\n}\r\n\r\n    .item-price.editable {\r\n        cursor: pointer;\r\n        border-bottom: 1px dashed var(--color-border-dashed);\r\n        transition: border-color var(--transition-fast), color var(--transition-fast);\r\n    }\r\n\r\n    .item-price:disabled {\r\n        cursor: default;\r\n        opacity: 1;\r\n    }\r\n\r\n    .item-price:focus-visible {\r\n        outline: 2px solid var(--color-accent);\r\n        outline-offset: 3px;\r\n        border-radius: 2px;\r\n    }\r\n\r\n@media (hover: hover) and (pointer: fine) {\r\n    .item-price.editable:hover {\r\n        border-color: var(--color-accent);\r\n        color: var(--color-accent);\r\n    }\r\n}\r\n\r\n/* --- �������������� ���� --- */\r\n\r\n.item-price-edit {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: var(--space-1);\r\n}\r\n\r\n.price-edit-input {\r\n    width: 80px;\r\n    padding: var(--space-1) var(--space-2);\r\n    border: 2px solid var(--color-accent);\r\n    border-radius: var(--radius-sm);\r\n    background-color: var(--color-bg-inset);\r\n    color: var(--color-text-primary);\r\n    font-family: var(--font-family-mono);\r\n    font-size: var(--font-size-md);\r\n    font-weight: var(--font-weight-bold);\r\n    text-align: right;\r\n    outline: none;\r\n    transition: border-color var(--transition-fast), box-shadow var(--transition-fast);\r\n}\r\n\r\n    .price-edit-input:focus-visible {\r\n        border-color: var(--color-accent-hover);\r\n        box-shadow: 0 0 0 3px var(--color-accent-soft);\r\n    }\r\n\r\n.price-edit-currency {\r\n    font-family: var(--font-family-mono);\r\n    font-weight: var(--font-weight-bold);\r\n    color: var(--color-text-tertiary);\r\n}\r\n\r\n/* --- ������ ������ --- */\r\n\r\n.item-bottom {\r\n    display: flex;\r\n    align-items: flex-start;\r\n    justify-content: space-between;\r\n    gap: var(--space-3);\r\n}\r\n\r\n.item-category-area {\r\n    flex: 1;\r\n    min-width: 0;\r\n}\r\n\r\n.item-category-editor {\r\n    display: block;\r\n    min-width: 0;\r\n}\r\n\r\n.item-category-select {\r\n    max-width: 220px;\r\n    width: 100%;\r\n    height: 32px;\r\n    padding: 0 var(--space-3);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-pill);\r\n    background-color: var(--color-bg-surface);\r\n    color: var(--color-text-primary);\r\n    font-size: var(--font-size-xs);\r\n    font-weight: var(--font-weight-medium);\r\n    outline: none;\r\n    cursor: pointer;\r\n    transition: border-color var(--transition-fast), background-color var(--transition-fast), color var(--transition-fast), box-shadow var(--transition-fast);\r\n}\r\n\r\n    .item-category-select:hover {\r\n        border-color: var(--color-border-hover);\r\n        background-color: var(--color-bg-surface-hover);\r\n    }\r\n\r\n    .item-category-select:focus-visible {\r\n        border-color: var(--color-accent);\r\n        box-shadow: 0 0 0 3px var(--color-accent-soft);\r\n    }\r\n\r\n.item-category-select--low-confidence {\r\n    border-color: var(--color-warning);\r\n    box-shadow: 0 0 0 2px var(--color-warning-soft);\r\n}\r\n\r\n.item-category-select--learned {\r\n    border-color: var(--color-accent);\r\n    box-shadow: 0 0 0 2px var(--color-accent-soft);\r\n}\r\n\r\n.item-category-hint {\r\n    margin-top: var(--space-1);\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 6px;\r\n    font-size: var(--font-size-xs);\r\n    color: var(--color-warning);\r\n    line-height: 1.2;\r\n}\r\n\r\n.item-category-hint--learned {\r\n    color: var(--color-accent);\r\n}\r\n\r\n.item-delete-btn {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    flex-shrink: 0;\r\n    padding: var(--space-1) var(--space-2);\r\n    border: none;\r\n    border-radius: var(--radius-sm);\r\n    background: none;\r\n    color: var(--color-text-placeholder);\r\n    cursor: pointer;\r\n    transition: color var(--transition-fast), background-color var(--transition-fast), transform var(--transition-fast);\r\n}\r\n\r\n    .item-delete-btn:active {\r\n        transform: scale(0.96);\r\n    }\r\n\r\n    .item-delete-btn:focus-visible {\r\n        outline: 2px solid var(--color-accent);\r\n        outline-offset: 2px;\r\n    }\r\n\r\n@media (hover: hover) and (pointer: fine) {\r\n    .item-delete-btn:hover {\r\n        color: var(--color-danger);\r\n        background-color: var(--color-danger-soft);\r\n    }\r\n}\r\n\r\n/* --- �������� --- */\r\n\r\n.receipt-item.removing {\r\n    animation: cv-item-slide-out 300ms ease-in forwards;\r\n    pointer-events: none;\r\n}\r\n\r\n@keyframes cv-item-slide-out {\r\n    0% {\r\n        opacity: 1;\r\n        max-height: 200px;\r\n    }\r\n\r\n    40% {\r\n        opacity: 0;\r\n    }\r\n\r\n    100% {\r\n        opacity: 0;\r\n        max-height: 0;\r\n        border-bottom-width: 0;\r\n        overflow: hidden;\r\n    }\r\n}\r\n\r\n.sr-only {\r\n    position: absolute;\r\n    width: 1px;\r\n    height: 1px;\r\n    padding: 0;\r\n    margin: -1px;\r\n    overflow: hidden;\r\n    clip: rect(0, 0, 0, 0);\r\n    white-space: nowrap;\r\n    border: 0;\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    .receipt-item,\r\n    .receipt-item-content,\r\n    .item-price,\r\n    .price-edit-input,\r\n    .item-delete-btn,\r\n    .item-category-select,\r\n    .receipt-item.removing {\r\n        animation: none !important;\r\n        transition: none !important;\r\n    }\r\n}\r\n","/* src/components/ReceiptItemList.css */\r\n\r\n.receipt-item-list {\r\n\tposition: relative;\r\n\toverflow: hidden;\r\n\tmargin: 0;\r\n\tpadding: 0;\r\n\tlist-style: none;\r\n\tborder: 1px solid var(--color-border);\r\n\tborder-radius: var(--radius-lg);\r\n\tbackground-color: var(--color-bg-surface);\r\n\tbox-shadow: var(--shadow-xs);\r\n}\r\n\r\n\t/* Декоративный «зубчатый» край */\r\n\t.receipt-item-list::after {\r\n\t\tcontent: '';\r\n\t\tdisplay: block;\r\n\t\theight: 10px;\r\n\t\tpointer-events: none;\r\n\t\tbackground: linear-gradient( -45deg, var(--color-bg-primary) 4px, transparent 0 ) left / 8px 100% repeat-x, linear-gradient( 45deg, var(--color-bg-primary) 4px, transparent 0 ) left / 8px 100% repeat-x;\r\n\t\tborder-radius: 0 0 var(--radius-lg) var(--radius-lg);\r\n\t}\r\n","/* src/components/ReceiptTotal.css */\r\n\r\n/* ============================================\r\n   ������ ��������\r\n   ============================================ */\r\n\r\n.receipt-total {\r\n    margin-top: var(--space-4);\r\n    padding: var(--space-5) var(--space-6);\r\n\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-lg);\r\n    background-color: var(--color-bg-surface);\r\n    box-shadow: var(--shadow-xs);\r\n}\r\n\r\n.receipt-total-row {\r\n    display: flex;\r\n    align-items: flex-end;\r\n    justify-content: space-between;\r\n    gap: var(--space-4);\r\n}\r\n\r\n.receipt-total-label {\r\n    font-size: var(--font-size-base);\r\n    font-weight: var(--font-weight-medium);\r\n    color: var(--color-text-secondary);\r\n    white-space: nowrap;\r\n}\r\n\r\n.receipt-total-amount {\r\n    font-family: var(--font-family-mono);\r\n    font-size: var(--font-size-2xl);\r\n    font-weight: var(--font-weight-bold);\r\n    line-height: 1;\r\n    color: var(--color-accent);\r\n    white-space: nowrap;\r\n}\r\n\r\n.receipt-total-amount.is-bumping {\r\n    animation: cv-receipt-total-bump 300ms ease-out;\r\n}\r\n\r\n@keyframes cv-receipt-total-bump {\r\n    0% {\r\n        opacity: 0.75;\r\n        transform: scale(0.98);\r\n    }\r\n    100% {\r\n        opacity: 1;\r\n        transform: scale(1);\r\n    }\r\n}\r\n\r\n.receipt-total-count {\r\n    margin-top: var(--space-1);\r\n\r\n    font-size: var(--font-size-sm);\r\n    line-height: 1.4;\r\n    color: var(--color-text-tertiary);\r\n    text-align: right;\r\n}\r\n\r\n/* ============================================\r\n   ���������� �������\r\n   ============================================ */\r\n\r\n.receipt-total--compact {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: var(--space-3);\r\n\r\n    margin: 0;\r\n    padding: var(--space-3) var(--space-5);\r\n\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-pill);\r\n    background-color: var(--color-bg-elevated);\r\n    box-shadow: var(--shadow-md);\r\n}\r\n\r\n.receipt-total--compact .receipt-total-row {\r\n    align-items: baseline;\r\n    justify-content: flex-start;\r\n    gap: var(--space-2);\r\n}\r\n\r\n.receipt-total--compact .receipt-total-label {\r\n    font-size: var(--font-size-sm);\r\n}\r\n\r\n.receipt-total--compact .receipt-total-amount {\r\n    font-size: var(--font-size-lg);\r\n}\r\n\r\n.receipt-total--compact .receipt-total-count {\r\n    margin-top: 0;\r\n    font-size: var(--font-size-xs);\r\n    line-height: 1;\r\n    color: var(--color-text-tertiary);\r\n    white-space: nowrap;\r\n}\r\n\r\n.receipt-total-divider {\r\n    font-size: var(--font-size-sm);\r\n    line-height: 1;\r\n    color: var(--color-text-placeholder);\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    .receipt-total-amount.is-bumping {\r\n        animation: none !important;\r\n    }\r\n}","/* src/components/EmptyState.css */\r\n\r\n.empty-state {\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    justify-content: center;\r\n    padding: var(--space-16) var(--space-6);\r\n    text-align: center;\r\n    animation: cv-empty-state-in var(--transition-slow) ease-out both;\r\n}\r\n\r\n@keyframes cv-empty-state-in {\r\n    from {\r\n        opacity: 0;\r\n        transform: translateY(8px);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: translateY(0);\r\n    }\r\n}\r\n\r\n.empty-state-icon {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    width: 80px;\r\n    height: 80px;\r\n    margin-bottom: var(--space-4);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: 999px;\r\n    background-color: var(--color-bg-inset);\r\n    color: var(--color-text-placeholder);\r\n    flex-shrink: 0;\r\n}\r\n\r\n    .empty-state-icon svg {\r\n        display: block;\r\n    }\r\n\r\n.empty-state-title {\r\n    margin-bottom: var(--space-2);\r\n    font-size: var(--font-size-lg);\r\n    font-weight: var(--font-weight-semibold);\r\n    line-height: 1.3;\r\n    color: var(--color-text-secondary);\r\n}\r\n\r\n.empty-state-subtitle {\r\n    max-width: 280px;\r\n    font-size: var(--font-size-sm);\r\n    line-height: var(--line-height-relaxed);\r\n    color: var(--color-text-tertiary);\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    .empty-state {\r\n        animation: none !important;\r\n    }\r\n}\r\n","/* src/components/ConfirmDialog.css */\r\n\r\n.confirm-overlay {\r\n    position: fixed;\r\n    inset: 0;\r\n    z-index: 500;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    padding: var(--space-4);\r\n    background-color: var(--color-overlay);\r\n    animation: cv-confirm-overlay-in var(--transition-base) ease-out both;\r\n}\r\n\r\n@keyframes cv-confirm-overlay-in {\r\n    from {\r\n        opacity: 0;\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n    }\r\n}\r\n\r\n.confirm-dialog {\r\n    width: 100%;\r\n    max-width: 380px;\r\n    padding: var(--space-7);\r\n    background-color: var(--color-bg-elevated);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-xl);\r\n    box-shadow: var(--shadow-dialog);\r\n    animation: cv-confirm-dialog-in 250ms cubic-bezier(0.34, 1.56, 0.64, 1) both;\r\n}\r\n\r\n@keyframes cv-confirm-dialog-in {\r\n    from {\r\n        opacity: 0;\r\n        transform: translateY(10px) scale(0.98);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: translateY(0) scale(1);\r\n    }\r\n}\r\n\r\n.confirm-title {\r\n    margin-bottom: var(--space-3);\r\n    font-size: var(--font-size-lg);\r\n    font-weight: var(--font-weight-bold);\r\n    line-height: 1.25;\r\n    color: var(--color-text-primary);\r\n}\r\n\r\n.confirm-message {\r\n    margin-bottom: var(--space-6);\r\n    font-size: var(--font-size-sm);\r\n    line-height: var(--line-height-relaxed);\r\n    color: var(--color-text-secondary);\r\n}\r\n\r\n.confirm-buttons {\r\n    display: flex;\r\n    gap: var(--space-3);\r\n}\r\n\r\n.confirm-btn {\r\n    flex: 1;\r\n    border: none;\r\n    border-radius: var(--radius-md);\r\n    padding: var(--space-3) var(--space-4);\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-semibold);\r\n    cursor: pointer;\r\n    transition: background-color var(--transition-fast), color var(--transition-fast), transform var(--transition-fast), box-shadow var(--transition-fast);\r\n}\r\n\r\n    .confirm-btn:active {\r\n        transform: scale(0.97);\r\n    }\r\n\r\n    .confirm-btn:focus-visible {\r\n        outline: 2px solid var(--color-accent);\r\n        outline-offset: 2px;\r\n    }\r\n\r\n    .confirm-btn.cancel {\r\n        background-color: var(--color-bg-inset);\r\n        color: var(--color-text-secondary);\r\n    }\r\n\r\n        .confirm-btn.cancel:hover {\r\n            background-color: var(--color-border);\r\n            color: var(--color-text-primary);\r\n        }\r\n\r\n    .confirm-btn.confirm {\r\n        background-color: var(--color-accent);\r\n        color: var(--color-text-inverse);\r\n    }\r\n\r\n        .confirm-btn.confirm:hover {\r\n            background-color: var(--color-accent-hover);\r\n        }\r\n\r\n        .confirm-btn.confirm.danger {\r\n            background-color: var(--color-danger);\r\n        }\r\n\r\n            .confirm-btn.confirm.danger:hover {\r\n                background-color: var(--color-danger-hover);\r\n            }\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    .confirm-overlay,\r\n    .confirm-dialog,\r\n    .confirm-btn {\r\n        animation: none !important;\r\n        transition: none !important;\r\n    }\r\n}\r\n","/* src/components/VoiceIndicator.css */\r\n\r\n.voice-indicator {\r\n    position: relative;\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    gap: var(--space-2);\r\n    min-height: 36px;\r\n    padding: var(--space-2) var(--space-4);\r\n    border: 1px solid var(--color-accent-medium);\r\n    border-radius: var(--radius-pill);\r\n    background-color: var(--color-accent-soft);\r\n    color: var(--color-accent);\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-medium);\r\n    line-height: 1;\r\n    white-space: nowrap;\r\n    transform: translateZ(0);\r\n    backface-visibility: hidden;\r\n    will-change: opacity, transform;\r\n    animation: cv-voice-indicator-in 180ms ease-out both;\r\n}\r\n\r\n@keyframes cv-voice-indicator-in {\r\n    from {\r\n        opacity: 0;\r\n        transform: translateY(4px) translateZ(0);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: translateY(0) translateZ(0);\r\n    }\r\n}\r\n\r\n/* ������������ ����� */\r\n.voice-indicator-dot {\r\n    width: 8px;\r\n    height: 8px;\r\n    border-radius: 999px;\r\n    background-color: currentColor;\r\n    flex-shrink: 0;\r\n    animation: cv-voice-dot-pulse 1.1s ease-in-out infinite;\r\n    transform: translateZ(0);\r\n    backface-visibility: hidden;\r\n    will-change: transform, opacity;\r\n}\r\n\r\n@keyframes cv-voice-dot-pulse {\r\n    0%, 100% {\r\n        opacity: 1;\r\n        transform: scale(1) translateZ(0);\r\n    }\r\n\r\n    50% {\r\n        opacity: 0.45;\r\n        transform: scale(0.78) translateZ(0);\r\n    }\r\n}\r\n\r\n/* �������� �������� */\r\n.voice-indicator-bars {\r\n    display: flex;\r\n    align-items: flex-end;\r\n    gap: 2px;\r\n    height: 18px;\r\n    flex-shrink: 0;\r\n    transform: translateZ(0);\r\n}\r\n\r\n.voice-indicator-bar {\r\n    width: 3px;\r\n    height: 18px;\r\n    border-radius: 999px;\r\n    background-color: currentColor;\r\n    transform-origin: center bottom;\r\n    transform: scaleY(0.35) translateZ(0);\r\n    opacity: 0.55;\r\n    animation: cv-voice-bar-bounce 900ms ease-in-out infinite;\r\n    will-change: transform, opacity;\r\n    backface-visibility: hidden;\r\n}\r\n\r\n    .voice-indicator-bar:nth-child(1) {\r\n        animation-delay: 0ms;\r\n    }\r\n\r\n    .voice-indicator-bar:nth-child(2) {\r\n        animation-delay: 100ms;\r\n    }\r\n\r\n    .voice-indicator-bar:nth-child(3) {\r\n        animation-delay: 200ms;\r\n    }\r\n\r\n    .voice-indicator-bar:nth-child(4) {\r\n        animation-delay: 300ms;\r\n    }\r\n\r\n    .voice-indicator-bar:nth-child(5) {\r\n        animation-delay: 400ms;\r\n    }\r\n\r\n        .voice-indicator-bar:nth-child(1)::before,\r\n        .voice-indicator-bar:nth-child(2)::before,\r\n        .voice-indicator-bar:nth-child(3)::before,\r\n        .voice-indicator-bar:nth-child(4)::before,\r\n        .voice-indicator-bar:nth-child(5)::before {\r\n            content: '';\r\n            display: block;\r\n            width: 100%;\r\n            height: 100%;\r\n            border-radius: inherit;\r\n            background: currentColor;\r\n        }\r\n\r\n    .voice-indicator-bar:nth-child(1) {\r\n        height: 8px;\r\n    }\r\n\r\n    .voice-indicator-bar:nth-child(2) {\r\n        height: 12px;\r\n    }\r\n\r\n    .voice-indicator-bar:nth-child(3) {\r\n        height: 18px;\r\n    }\r\n\r\n    .voice-indicator-bar:nth-child(4) {\r\n        height: 12px;\r\n    }\r\n\r\n    .voice-indicator-bar:nth-child(5) {\r\n        height: 8px;\r\n    }\r\n\r\n@keyframes cv-voice-bar-bounce {\r\n    0%, 100% {\r\n        opacity: 0.45;\r\n        transform: scaleY(0.45) translateZ(0);\r\n    }\r\n\r\n    50% {\r\n        opacity: 1;\r\n        transform: scaleY(1) translateZ(0);\r\n    }\r\n}\r\n\r\n/* ����� */\r\n.voice-indicator-text {\r\n    display: inline-block;\r\n    white-space: nowrap;\r\n}\r\n\r\n/* ������ */\r\n.voice-indicator svg {\r\n    flex-shrink: 0;\r\n    display: block;\r\n}\r\n\r\n/* ������� */\r\n.voice-indicator--listening {\r\n    background-color: var(--color-accent-soft);\r\n    border-color: var(--color-accent-medium);\r\n    color: var(--color-accent);\r\n}\r\n\r\n.voice-indicator--processing {\r\n    background-color: var(--color-secondary-soft);\r\n    border-color: var(--color-secondary-medium);\r\n    color: var(--color-secondary);\r\n}\r\n\r\n.voice-indicator--success {\r\n    background-color: var(--color-success-soft);\r\n    border-color: var(--color-success);\r\n    color: var(--color-success);\r\n}\r\n\r\n.voice-indicator--error {\r\n    background-color: var(--color-danger-soft);\r\n    border-color: var(--color-danger-medium);\r\n    color: var(--color-danger);\r\n}\r\n\r\n/* ����� ������ ��������� success/error */\r\n.voice-indicator--success,\r\n.voice-indicator--error {\r\n    animation-duration: 140ms;\r\n}\r\n\r\n/* �������� ��������� �������� */\r\n@media (prefers-reduced-motion: reduce) {\r\n    .voice-indicator,\r\n    .voice-indicator-dot,\r\n    .voice-indicator-bar {\r\n        animation: none !important;\r\n    }\r\n\r\n    .voice-indicator-dot,\r\n    .voice-indicator-bar {\r\n        opacity: 1 !important;\r\n        transform: none !important;\r\n    }\r\n}\r\n","/* src/components/SaveAnimation.css */\r\n\r\n.save-animation {\r\n    position: absolute;\r\n    inset: 0;\r\n    z-index: 60;\r\n    overflow: hidden;\r\n    border-radius: var(--radius-lg);\r\n    pointer-events: none;\r\n    isolation: isolate;\r\n    will-change: opacity, transform;\r\n    transform: translateZ(0);\r\n    backface-visibility: hidden;\r\n}\r\n\r\n/* ��� */\r\n.save-animation-backdrop {\r\n    position: absolute;\r\n    inset: 0;\r\n    background-color: rgba(255, 255, 255, 0.82);\r\n    backdrop-filter: blur(6px);\r\n    -webkit-backdrop-filter: blur(6px);\r\n    animation: cv-save-backdrop-in 220ms ease-out both;\r\n    will-change: opacity;\r\n    transform: translateZ(0);\r\n}\r\n\r\n[data-theme=\"dark\"] .save-animation-backdrop,\r\n[data-theme=\"midnight\"] .save-animation-backdrop {\r\n    background-color: rgba(0, 0, 0, 0.62);\r\n}\r\n\r\n@keyframes cv-save-backdrop-in {\r\n    from {\r\n        opacity: 0;\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n    }\r\n}\r\n\r\n/* ����� �����, �� ������� �� ������������ */\r\n.save-animation-center {\r\n    position: absolute;\r\n    top: 50%;\r\n    left: 50%;\r\n    width: 240px;\r\n    height: 240px;\r\n    transform: translate(-50%, -50%) translateZ(0);\r\n    transform-origin: center center;\r\n    will-change: transform, opacity;\r\n    backface-visibility: hidden;\r\n}\r\n\r\n/* ����������� ���� */\r\n.save-animation-circle {\r\n    position: absolute;\r\n    top: 50%;\r\n    left: 50%;\r\n    width: 180px;\r\n    height: 180px;\r\n    border-radius: 50%;\r\n    background: radial-gradient( circle, var(--color-accent) 0%, var(--color-accent-hover) 100% );\r\n    box-shadow: 0 0 20px var(--color-accent-soft), 0 0 40px var(--color-accent-soft);\r\n    opacity: 0;\r\n    transform: translate(-50%, -50%) scale(0.15) translateZ(0);\r\n    transform-origin: center center;\r\n    animation: cv-save-circle-grow 420ms cubic-bezier(0.16, 1, 0.3, 1) 80ms forwards;\r\n    will-change: transform, opacity;\r\n    backface-visibility: hidden;\r\n}\r\n\r\n@keyframes cv-save-circle-grow {\r\n    0% {\r\n        opacity: 0;\r\n        transform: translate(-50%, -50%) scale(0.15) translateZ(0);\r\n    }\r\n\r\n    60% {\r\n        opacity: 1;\r\n        transform: translate(-50%, -50%) scale(1.05) translateZ(0);\r\n    }\r\n\r\n    100% {\r\n        opacity: 1;\r\n        transform: translate(-50%, -50%) scale(1) translateZ(0);\r\n    }\r\n}\r\n\r\n/* SVG */\r\n.save-animation-check {\r\n    position: absolute;\r\n    top: 50%;\r\n    left: 50%;\r\n    z-index: 3;\r\n    width: 72px;\r\n    height: 72px;\r\n    opacity: 0;\r\n    transform: translate(-50%, -50%) scale(0.72) rotate(-8deg) translateZ(0);\r\n    transform-origin: center center;\r\n    animation: cv-save-check-pop 320ms cubic-bezier(0.34, 1.56, 0.64, 1) 320ms forwards;\r\n    will-change: transform, opacity;\r\n    backface-visibility: hidden;\r\n}\r\n\r\n    .save-animation-check svg,\r\n    svg.save-animation-check {\r\n        display: block;\r\n        overflow: visible;\r\n    }\r\n\r\n@keyframes cv-save-check-pop {\r\n    0% {\r\n        opacity: 0;\r\n        transform: translate(-50%, -50%) scale(0.72) rotate(-8deg) translateZ(0);\r\n    }\r\n\r\n    60% {\r\n        opacity: 1;\r\n        transform: translate(-50%, -50%) scale(1.08) rotate(1deg) translateZ(0);\r\n    }\r\n\r\n    100% {\r\n        opacity: 1;\r\n        transform: translate(-50%, -50%) scale(1) rotate(0deg) translateZ(0);\r\n    }\r\n}\r\n\r\n/* ������ */\r\n.save-animation-ring {\r\n    fill: none;\r\n    stroke: rgba(255, 255, 255, 0.92);\r\n    stroke-width: 2.5;\r\n    stroke-linecap: round;\r\n    stroke-linejoin: round;\r\n    stroke-dasharray: 204.2;\r\n    stroke-dashoffset: 204.2;\r\n    animation: cv-save-ring-draw 520ms ease-out 430ms forwards;\r\n    shape-rendering: geometricPrecision;\r\n}\r\n\r\n.save-animation-tick {\r\n    fill: none;\r\n    stroke: #ffffff;\r\n    stroke-width: 4.5;\r\n    stroke-linecap: round;\r\n    stroke-linejoin: round;\r\n    stroke-dasharray: 40;\r\n    stroke-dashoffset: 40;\r\n    animation: cv-save-tick-draw 260ms ease-out 620ms forwards;\r\n    shape-rendering: geometricPrecision;\r\n}\r\n\r\n@keyframes cv-save-tick-draw {\r\n    to {\r\n        stroke-dashoffset: 0;\r\n    }\r\n}\r\n\r\n/* ������ */\r\n.save-animation-pulse {\r\n    position: absolute;\r\n    top: 50%;\r\n    left: 50%;\r\n    z-index: 2;\r\n    width: 72px;\r\n    height: 72px;\r\n    border-radius: 50%;\r\n    border: 2px solid rgba(255, 255, 255, 0.34);\r\n    opacity: 0;\r\n    transform: translate(-50%, -50%) scale(1) translateZ(0);\r\n    transform-origin: center center;\r\n    will-change: transform, opacity;\r\n    backface-visibility: hidden;\r\n}\r\n\r\n.save-animation-pulse--1 {\r\n    animation: cv-save-pulse-expand 620ms ease-out 700ms forwards;\r\n}\r\n\r\n.save-animation-pulse--2 {\r\n    animation: cv-save-pulse-expand 620ms ease-out 840ms forwards;\r\n}\r\n\r\n@keyframes cv-save-pulse-expand {\r\n    0% {\r\n        opacity: 0.42;\r\n        transform: translate(-50%, -50%) scale(1) translateZ(0);\r\n    }\r\n\r\n    100% {\r\n        opacity: 0;\r\n        transform: translate(-50%, -50%) scale(2.3) translateZ(0);\r\n    }\r\n}\r\n\r\n/* ������� */\r\n.save-animation-particles {\r\n    position: absolute;\r\n    top: 50%;\r\n    left: 50%;\r\n    z-index: 4;\r\n    width: 180px;\r\n    height: 180px;\r\n    transform: translate(-50%, -50%) translateZ(0);\r\n    pointer-events: none;\r\n    will-change: transform;\r\n}\r\n\r\n.save-animation-particle {\r\n    position: absolute;\r\n    top: 50%;\r\n    left: 50%;\r\n    width: 6px;\r\n    height: 6px;\r\n    margin-top: -3px;\r\n    margin-left: -3px;\r\n    border-radius: 50%;\r\n    background-color: rgba(255, 255, 255, 0.82);\r\n    opacity: 0;\r\n    transform: translate3d(0, 0, 0) scale(0.8);\r\n    will-change: transform, opacity;\r\n    backface-visibility: hidden;\r\n}\r\n\r\n    .save-animation-particle:nth-child(1) {\r\n        --px: -34px;\r\n        --py: -42px;\r\n        animation: cv-particle-burst 520ms ease-out 680ms forwards;\r\n    }\r\n\r\n    .save-animation-particle:nth-child(2) {\r\n        --px: 38px;\r\n        --py: -30px;\r\n        animation: cv-particle-burst 520ms ease-out 720ms forwards;\r\n    }\r\n\r\n    .save-animation-particle:nth-child(3) {\r\n        --px: 42px;\r\n        --py: 26px;\r\n        animation: cv-particle-burst 520ms ease-out 700ms forwards;\r\n    }\r\n\r\n    .save-animation-particle:nth-child(4) {\r\n        --px: -30px;\r\n        --py: 38px;\r\n        animation: cv-particle-burst 520ms ease-out 740ms forwards;\r\n    }\r\n\r\n    .save-animation-particle:nth-child(5) {\r\n        --px: -46px;\r\n        --py: 4px;\r\n        animation: cv-particle-burst 520ms ease-out 710ms forwards;\r\n    }\r\n\r\n    .save-animation-particle:nth-child(6) {\r\n        --px: 26px;\r\n        --py: -46px;\r\n        animation: cv-particle-burst 520ms ease-out 750ms forwards;\r\n    }\r\n\r\n@keyframes cv-particle-burst {\r\n    0% {\r\n        opacity: 0;\r\n        transform: translate3d(0, 0, 0) scale(0.8);\r\n    }\r\n\r\n    18% {\r\n        opacity: 1;\r\n        transform: translate3d(calc(var(--px) * 0.35), calc(var(--py) * 0.35), 0) scale(1);\r\n    }\r\n\r\n    100% {\r\n        opacity: 0;\r\n        transform: translate3d(var(--px), var(--py), 0) scale(0.35);\r\n    }\r\n}\r\n\r\n/* ����� */\r\n.save-animation-text {\r\n    position: absolute;\r\n    top: calc(50% + 112px);\r\n    left: 50%;\r\n    z-index: 5;\r\n    min-width: 160px;\r\n    text-align: center;\r\n    opacity: 0;\r\n    transform: translate(-50%, 8px) translateZ(0);\r\n    animation: cv-save-text-appear 260ms ease-out 820ms forwards;\r\n    will-change: transform, opacity;\r\n    backface-visibility: hidden;\r\n}\r\n\r\n.save-animation-text-main {\r\n    display: block;\r\n    margin-bottom: var(--space-1);\r\n    font-size: var(--font-size-lg);\r\n    font-weight: var(--font-weight-bold);\r\n    line-height: 1.2;\r\n    color: var(--color-accent);\r\n}\r\n\r\n.save-animation-text-sub {\r\n    display: block;\r\n    font-family: var(--font-family-mono);\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-semibold);\r\n    line-height: 1.2;\r\n    color: var(--color-text-secondary);\r\n}\r\n\r\n@keyframes cv-save-text-appear {\r\n    0% {\r\n        opacity: 0;\r\n        transform: translate(-50%, 8px) translateZ(0);\r\n    }\r\n\r\n    100% {\r\n        opacity: 1;\r\n        transform: translate(-50%, 0) translateZ(0);\r\n    }\r\n}\r\n\r\n/* ����� ������� */\r\n.save-animation.fading {\r\n    animation: cv-save-all-fadeout 240ms ease-in forwards;\r\n}\r\n\r\n@keyframes cv-save-all-fadeout {\r\n    0% {\r\n        opacity: 1;\r\n        transform: translateZ(0);\r\n    }\r\n\r\n    100% {\r\n        opacity: 0;\r\n        transform: translateZ(0);\r\n    }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    .save-animation-backdrop,\r\n    .save-animation-circle,\r\n    .save-animation-check,\r\n    .save-animation-ring,\r\n    .save-animation-tick,\r\n    .save-animation-pulse,\r\n    .save-animation-particle,\r\n    .save-animation-text,\r\n    .save-animation.fading {\r\n        animation-duration: 1ms !important;\r\n        animation-delay: 0ms !important;\r\n    }\r\n\r\n    .save-animation-backdrop,\r\n    .save-animation-circle,\r\n    .save-animation-check,\r\n    .save-animation-text {\r\n        opacity: 1 !important;\r\n    }\r\n\r\n    .save-animation-circle {\r\n        transform: translate(-50%, -50%) scale(1) translateZ(0) !important;\r\n    }\r\n\r\n    .save-animation-check {\r\n        transform: translate(-50%, -50%) scale(1) rotate(0deg) translateZ(0) !important;\r\n    }\r\n\r\n    .save-animation-text {\r\n        transform: translate(-50%, 0) translateZ(0) !important;\r\n    }\r\n}\r\n","/* src/components/CategoryReviewPrompt.css */\r\n\r\n.category-review-prompt {\r\n    margin-bottom: var(--space-4);\r\n    padding: var(--space-4);\r\n    border: 1px solid var(--color-warning-soft);\r\n    border-radius: var(--radius-lg);\r\n    background-color: var(--color-bg-surface);\r\n    box-shadow: var(--shadow-xs);\r\n}\r\n\r\n.category-review-header {\r\n    display: flex;\r\n    align-items: flex-start;\r\n    justify-content: space-between;\r\n    gap: var(--space-3);\r\n}\r\n\r\n.category-review-title-wrap {\r\n    display: flex;\r\n    align-items: flex-start;\r\n    gap: var(--space-3);\r\n    min-width: 0;\r\n}\r\n\r\n.category-review-icon {\r\n    width: 32px;\r\n    height: 32px;\r\n    border-radius: var(--radius-pill);\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    flex-shrink: 0;\r\n    color: var(--color-warning);\r\n    background-color: var(--color-warning-soft);\r\n}\r\n\r\n.category-review-text {\r\n    min-width: 0;\r\n}\r\n\r\n.category-review-title {\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-semibold);\r\n    color: var(--color-text-primary);\r\n}\r\n\r\n.category-review-subtitle {\r\n    margin-top: 2px;\r\n    font-size: var(--font-size-xs);\r\n    color: var(--color-text-tertiary);\r\n}\r\n\r\n.category-review-actions {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: var(--space-2);\r\n    flex-shrink: 0;\r\n}\r\n\r\n.category-review-btn {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    gap: 6px;\r\n    height: 32px;\r\n    padding: 0 var(--space-3);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-pill);\r\n    background-color: var(--color-bg-surface);\r\n    color: var(--color-text-secondary);\r\n    font-size: var(--font-size-xs);\r\n    font-weight: var(--font-weight-medium);\r\n    cursor: pointer;\r\n    transition: background-color var(--transition-fast), border-color var(--transition-fast), color var(--transition-fast), box-shadow var(--transition-fast);\r\n}\r\n\r\n    .category-review-btn:hover {\r\n        background-color: var(--color-bg-surface-hover);\r\n        border-color: var(--color-border-hover);\r\n        color: var(--color-text-primary);\r\n    }\r\n\r\n.category-review-btn--ghost {\r\n    background: none;\r\n    border-color: transparent;\r\n    color: var(--color-text-tertiary);\r\n}\r\n\r\n    .category-review-btn--ghost:hover {\r\n        background-color: var(--color-bg-inset);\r\n        border-color: transparent;\r\n        color: var(--color-text-primary);\r\n    }\r\n\r\n.category-review-list {\r\n    margin-top: var(--space-4);\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: var(--space-3);\r\n}\r\n\r\n.category-review-item {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    gap: var(--space-3);\r\n    padding: var(--space-3);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-md);\r\n    background-color: var(--color-bg-inset);\r\n}\r\n\r\n.category-review-item-main {\r\n    min-width: 0;\r\n    flex: 1;\r\n}\r\n\r\n.category-review-item-title {\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-semibold);\r\n    color: var(--color-text-primary);\r\n    word-break: break-word;\r\n}\r\n\r\n.category-review-item-reason {\r\n    margin-top: 2px;\r\n    font-size: var(--font-size-xs);\r\n    color: var(--color-text-tertiary);\r\n}\r\n\r\n.category-review-item-controls {\r\n    flex-shrink: 0;\r\n    width: 220px;\r\n    max-width: 100%;\r\n}\r\n\r\n.category-review-select {\r\n    width: 100%;\r\n    height: 36px;\r\n    padding: 0 var(--space-3);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-pill);\r\n    background-color: var(--color-bg-surface);\r\n    color: var(--color-text-primary);\r\n    font-size: var(--font-size-xs);\r\n    font-weight: var(--font-weight-medium);\r\n    outline: none;\r\n    cursor: pointer;\r\n    transition: border-color var(--transition-fast), background-color var(--transition-fast), box-shadow var(--transition-fast);\r\n}\r\n\r\n    .category-review-select:hover {\r\n        border-color: var(--color-border-hover);\r\n        background-color: var(--color-bg-surface-hover);\r\n    }\r\n\r\n    .category-review-select:focus-visible {\r\n        border-color: var(--color-accent);\r\n        box-shadow: 0 0 0 3px var(--color-accent-soft);\r\n    }\r\n\r\n.category-review-footer {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 6px;\r\n    margin-top: var(--space-1);\r\n    font-size: var(--font-size-xs);\r\n    color: var(--color-accent);\r\n}\r\n\r\n@media (max-width: 640px) {\r\n    .category-review-header {\r\n        flex-direction: column;\r\n        align-items: stretch;\r\n    }\r\n\r\n    .category-review-actions {\r\n        justify-content: flex-start;\r\n        flex-wrap: wrap;\r\n    }\r\n\r\n    .category-review-item {\r\n        flex-direction: column;\r\n        align-items: stretch;\r\n    }\r\n\r\n    .category-review-item-controls {\r\n        width: 100%;\r\n    }\r\n}\r\n","/* src/pages/NewReceipt.css */\r\n\r\n.new-receipt {\r\n    display: flex;\r\n    flex-direction: column;\r\n    position: relative;\r\n    height: calc(100vh - var(--nav-height) - var(--assistant-panel-height) - 40px);\r\n    min-height: 280px;\r\n    overflow: hidden;\r\n}\r\n\r\n@supports (height: 100dvh) {\r\n    .new-receipt {\r\n        height: calc(100dvh - var(--nav-height) - var(--assistant-panel-height) - 40px);\r\n    }\r\n}\r\n\r\n/* --- Шапка --- */\r\n\r\n.new-receipt .page-header {\r\n    flex-shrink: 0;\r\n    margin-bottom: var(--space-3);\r\n}\r\n\r\n.receipt-header-meta {\r\n    display: flex;\r\n    flex-direction: column;\r\n}\r\n\r\n.receipt-header-right {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: var(--space-3);\r\n}\r\n\r\n.receipt-header-actions {\r\n    display: flex;\r\n    gap: var(--space-3);\r\n}\r\n\r\n.receipt-action-icon {\r\n    width: 36px;\r\n    height: 36px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    border: none;\r\n    border-radius: var(--radius-sm);\r\n    background: none;\r\n    color: var(--color-text-tertiary);\r\n    cursor: pointer;\r\n    transition: all var(--transition-fast);\r\n}\r\n\r\n    .receipt-action-icon:hover {\r\n        background-color: var(--color-bg-inset);\r\n        color: var(--color-text-secondary);\r\n    }\r\n\r\n.receipt-action-icon--clear {\r\n    color: var(--color-danger);\r\n    background-color: var(--color-danger-soft);\r\n}\r\n\r\n    .receipt-action-icon--clear:hover {\r\n        background-color: var(--color-danger-medium);\r\n        color: var(--color-danger);\r\n    }\r\n\r\n.receipt-action-icon--save {\r\n    background-color: var(--color-accent-soft);\r\n    color: var(--color-accent);\r\n}\r\n\r\n    .receipt-action-icon--save:hover {\r\n        background-color: var(--color-accent-medium);\r\n        color: var(--color-accent-hover);\r\n    }\r\n\r\n/* --- Область прокрутки (основное тело) --- */\r\n\r\n.receipt-scroll-area {\r\n    flex: 1 1 0%;\r\n    overflow-y: auto;\r\n    overflow-x: hidden;\r\n    min-height: 0;\r\n    -webkit-overflow-scrolling: touch;\r\n    scroll-behavior: smooth;\r\n    padding-bottom: var(--space-2);\r\n}\r\n\r\n    .receipt-scroll-area::-webkit-scrollbar {\r\n        width: 4px;\r\n    }\r\n\r\n    .receipt-scroll-area::-webkit-scrollbar-thumb {\r\n        background-color: var(--color-border);\r\n        border-radius: var(--radius-pill);\r\n    }\r\n\r\n    .receipt-scroll-area > .empty-state {\r\n        flex: 1;\r\n        padding: var(--space-8) var(--space-4);\r\n    }\r\n\r\n/* --- Итоговая сумма --- */\r\n\r\n.receipt-floating-total {\r\n    flex-shrink: 0;\r\n    padding: var(--space-4) 0 var(--space-2) 0;\r\n}\r\n\r\n/* --- Голосовой индикатор --- */\r\n\r\n.receipt-voice-area {\r\n    flex-shrink: 0;\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    padding: var(--space-4) 0 var(--space-5) 0;\r\n    position: relative;\r\n    z-index: 45;\r\n}\r\n\r\n/* --- Кнопка помощи --- */\r\n\r\n.receipt-help-btn {\r\n    position: fixed;\r\n    bottom: calc(var(--assistant-panel-height) + var(--space-6) + 10px);\r\n    right: var(--space-4);\r\n    width: 40px;\r\n    height: 40px;\r\n    border-radius: var(--radius-pill);\r\n    background-color: var(--color-bg-surface);\r\n    border: 1px solid var(--color-border);\r\n    box-shadow: var(--shadow-md);\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    color: var(--color-text-tertiary);\r\n    cursor: pointer;\r\n    transition: all var(--transition-fast);\r\n    z-index: 50;\r\n}\r\n\r\n    .receipt-help-btn:hover {\r\n        background-color: var(--color-bg-surface-hover);\r\n        color: var(--color-accent);\r\n        border-color: var(--color-accent-soft);\r\n        box-shadow: var(--shadow-lg);\r\n    }\r\n\r\n.receipt-action-icon:focus-visible,\r\n.receipt-help-btn:focus-visible {\r\n    outline: 2px solid var(--color-accent);\r\n    outline-offset: 2px;\r\n}\r\n\r\n/* ============================================\r\n   Help Dialog\r\n   ============================================ */\r\n\r\n.help-overlay {\r\n    position: fixed;\r\n    inset: 0;\r\n    z-index: 500;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    padding: var(--space-4);\r\n    background-color: var(--color-overlay);\r\n    animation: cv-confirm-overlay-in var(--transition-base) ease-out both;\r\n}\r\n\r\n.help-dialog {\r\n    width: 100%;\r\n    max-width: 480px;\r\n    /*\r\n      Оставляем снизу запас под панель ассистента Сбера + немного воздуха.\r\n      --assistant-panel-height уже учтён в токенах (76px).\r\n      Добавляем ещё 24px буфера чтобы последняя строка не попадала под блюр.\r\n    */\r\n    max-height: calc(100vh - var(--nav-height) - var(--assistant-panel-height) - 48px);\r\n    max-height: calc(100dvh - var(--nav-height) - var(--assistant-panel-height) - 48px);\r\n    display: flex;\r\n    flex-direction: column;\r\n    background-color: var(--color-bg-elevated);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-xl);\r\n    box-shadow: var(--shadow-dialog);\r\n    animation: cv-confirm-dialog-in 250ms cubic-bezier(0.34, 1.56, 0.64, 1) both;\r\n    overflow: hidden;\r\n}\r\n\r\n.help-dialog-header {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    padding: var(--space-5) var(--space-6);\r\n    border-bottom: 1px solid var(--color-border);\r\n    flex-shrink: 0;\r\n}\r\n\r\n.help-dialog-title {\r\n    font-size: var(--font-size-lg);\r\n    font-weight: var(--font-weight-bold);\r\n    color: var(--color-text-primary);\r\n}\r\n\r\n.help-dialog-close {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    width: 32px;\r\n    height: 32px;\r\n    border: none;\r\n    border-radius: var(--radius-sm);\r\n    background: none;\r\n    color: var(--color-text-tertiary);\r\n    cursor: pointer;\r\n    transition: background-color var(--transition-fast), color var(--transition-fast);\r\n    flex-shrink: 0;\r\n}\r\n\r\n    .help-dialog-close:hover {\r\n        background-color: var(--color-bg-inset);\r\n        color: var(--color-text-primary);\r\n    }\r\n\r\n    .help-dialog-close:focus-visible {\r\n        outline: 2px solid var(--color-accent);\r\n        outline-offset: 2px;\r\n    }\r\n\r\n.help-dialog-body {\r\n    flex: 1;\r\n    overflow-y: auto;\r\n    padding: var(--space-5) var(--space-6);\r\n    /* Дополнительный отступ снизу чтобы последняя строка не обрезалась */\r\n    padding-bottom: var(--space-7);\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: var(--space-5);\r\n    -webkit-overflow-scrolling: touch;\r\n}\r\n\r\n    .help-dialog-body::-webkit-scrollbar {\r\n        width: 4px;\r\n    }\r\n\r\n    .help-dialog-body::-webkit-scrollbar-thumb {\r\n        background-color: var(--color-border);\r\n        border-radius: var(--radius-pill);\r\n    }\r\n\r\n.help-dialog-intro {\r\n    font-size: var(--font-size-sm);\r\n    color: var(--color-text-secondary);\r\n    line-height: var(--line-height-relaxed);\r\n    margin: 0;\r\n}\r\n\r\n.help-section {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: var(--space-2);\r\n}\r\n\r\n.help-section-title {\r\n    font-size: var(--font-size-xs);\r\n    font-weight: var(--font-weight-bold);\r\n    text-transform: uppercase;\r\n    letter-spacing: var(--letter-spacing-caps);\r\n    color: var(--color-accent);\r\n}\r\n\r\n.help-section-list {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: var(--space-2);\r\n    list-style: none;\r\n    padding: 0;\r\n    margin: 0;\r\n}\r\n\r\n.help-section-item {\r\n    display: flex;\r\n    align-items: baseline;\r\n    gap: var(--space-3);\r\n    flex-wrap: wrap;\r\n}\r\n\r\n.help-example {\r\n    font-family: var(--font-family-mono);\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-semibold);\r\n    color: var(--color-text-primary);\r\n    background-color: var(--color-accent-soft);\r\n    padding: 2px var(--space-2);\r\n    border-radius: var(--radius-xs);\r\n    white-space: nowrap;\r\n}\r\n\r\n.help-desc {\r\n    font-size: var(--font-size-xs);\r\n    color: var(--color-text-tertiary);\r\n    line-height: 1.4;\r\n}\r\n\r\n.help-dialog-tip {\r\n    padding: var(--space-4);\r\n    border-radius: var(--radius-md);\r\n    background-color: var(--color-bg-inset);\r\n    font-size: var(--font-size-sm);\r\n    color: var(--color-text-secondary);\r\n    line-height: var(--line-height-relaxed);\r\n    /* Гарантируем что подсказка не обрезается на маленьких экранах */\r\n    flex-shrink: 0;\r\n}\r\n\r\n@media (max-width: 480px) {\r\n    .help-dialog-header {\r\n        padding: var(--space-4) var(--space-5);\r\n    }\r\n\r\n    .help-dialog-body {\r\n        padding: var(--space-4) var(--space-5) var(--space-7) var(--space-5);\r\n    }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    .help-overlay,\r\n    .help-dialog {\r\n        animation: none !important;\r\n    }\r\n}",".receipt-history {\r\n    padding-bottom: var(--space-8);\r\n}\r\n\r\n.history-count {\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-medium);\r\n    color: var(--color-text-tertiary);\r\n}\r\n\r\n/* --- ������ �� ���� --- */\r\n\r\n.history-date-group {\r\n    margin-bottom: var(--space-6);\r\n    animation: cv-fade-in-up var(--transition-slow) both;\r\n}\r\n\r\n.history-date-header {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    padding: var(--space-2) var(--space-1);\r\n    margin-bottom: var(--space-2);\r\n}\r\n\r\n.history-date-left {\r\n    display: flex;\r\n    align-items: center;\r\n    min-width: 0;\r\n}\r\n\r\n.history-date-label {\r\n    font-size: var(--font-size-xs);\r\n    font-weight: var(--font-weight-semibold);\r\n    color: var(--color-text-tertiary);\r\n    text-transform: uppercase;\r\n    letter-spacing: var(--letter-spacing-caps);\r\n}\r\n\r\n.history-date-total {\r\n    flex-shrink: 0;\r\n    font-family: var(--font-family-mono);\r\n    font-size: var(--font-size-xs);\r\n    font-weight: var(--font-weight-semibold);\r\n    color: var(--color-text-tertiary);\r\n}\r\n\r\n/* --- �������� ���� --- */\r\n\r\n.history-card {\r\n    width: 100%;\r\n    background-color: var(--color-bg-surface);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-lg);\r\n    padding: var(--space-4) var(--space-5);\r\n    margin-bottom: var(--space-2);\r\n    cursor: pointer;\r\n    text-align: left;\r\n    color: var(--color-text-primary);\r\n    box-shadow: var(--shadow-xs);\r\n    transition: background-color var(--transition-fast), border-color var(--transition-fast), box-shadow var(--transition-fast), transform var(--transition-fast);\r\n}\r\n\r\n    .history-card:hover {\r\n        background-color: var(--color-bg-surface-hover);\r\n        border-color: var(--color-border-hover);\r\n        box-shadow: var(--shadow-sm);\r\n    }\r\n\r\n    .history-card:active {\r\n        transform: scale(0.99);\r\n        box-shadow: var(--shadow-xs);\r\n    }\r\n\r\n    .history-card:focus-visible {\r\n        outline: 2px solid var(--color-accent);\r\n        outline-offset: 2px;\r\n        border-color: var(--color-accent);\r\n    }\r\n\r\n.history-card-top {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    margin-bottom: var(--space-2);\r\n}\r\n\r\n.history-card-count {\r\n    font-size: var(--font-size-sm);\r\n    color: var(--color-text-secondary);\r\n}\r\n\r\n.history-card-total {\r\n    font-family: var(--font-family-mono);\r\n    font-size: var(--font-size-lg);\r\n    font-weight: var(--font-weight-bold);\r\n    color: var(--color-text-primary);\r\n}\r\n\r\n.history-card-categories {\r\n    display: flex;\r\n    gap: var(--space-2);\r\n    flex-wrap: wrap;\r\n    align-items: center;\r\n}\r\n\r\n.history-card-cat-more {\r\n    font-size: var(--font-size-xs);\r\n    color: var(--color-text-tertiary);\r\n    align-self: center;\r\n}\r\n\r\n/* --- �������� ����� --- */\r\n\r\n.history-grand-total {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    padding: var(--space-4) var(--space-5);\r\n    margin-top: var(--space-4);\r\n    border-top: 2px dashed var(--color-border-dashed);\r\n    font-size: var(--font-size-lg);\r\n    font-weight: var(--font-weight-bold);\r\n    color: var(--color-text-secondary);\r\n}\r\n\r\n    .history-grand-total span:last-child {\r\n        font-family: var(--font-family-mono);\r\n        color: var(--color-accent);\r\n    }\r\n\r\n/* --- ������ ��� --- */\r\n\r\n.history-date-icon {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    width: 28px;\r\n    height: 28px;\r\n    border-radius: var(--radius-sm);\r\n    margin-right: var(--space-2);\r\n    flex-shrink: 0;\r\n    font-size: var(--font-size-xs);\r\n}\r\n\r\n.history-date-icon--today {\r\n    background-color: var(--color-accent-soft);\r\n    color: var(--color-accent);\r\n}\r\n\r\n.history-date-icon--yesterday {\r\n    background-color: var(--color-secondary-soft);\r\n    color: var(--color-secondary);\r\n}\r\n\r\n.history-date-icon--older {\r\n    background-color: var(--color-bg-inset);\r\n    color: var(--color-text-tertiary);\r\n}\r\n",".receipt-details {\r\n    padding-bottom: var(--space-8);\r\n}\r\n\r\n.details-header {\r\n    margin-bottom: var(--space-6);\r\n}\r\n\r\n/* ������ ������ */\r\n.back-btn {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: var(--space-1);\r\n    background: none;\r\n    border: none;\r\n    color: var(--color-text-tertiary);\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-medium);\r\n    cursor: pointer;\r\n    padding: var(--space-2) var(--space-2);\r\n    margin-bottom: var(--space-2);\r\n    margin-left: calc(var(--space-2) * -1);\r\n    border-radius: var(--radius-sm);\r\n    transition: color var(--transition-fast), background-color var(--transition-fast);\r\n}\r\n\r\n    .back-btn:hover {\r\n        color: var(--color-accent);\r\n        background-color: var(--color-bg-inset);\r\n    }\r\n\r\n/* ���� �������� */\r\n.details-actions {\r\n    margin-top: var(--space-6);\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: var(--space-2);\r\n}\r\n\r\n.edit-receipt-btn,\r\n.delete-receipt-btn {\r\n    width: 100%;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    gap: var(--space-2);\r\n    height: var(--btn-height);\r\n    border-radius: var(--radius-md);\r\n    font-size: var(--font-size-base);\r\n    font-weight: var(--font-weight-semibold);\r\n    cursor: pointer;\r\n    transition: all var(--transition-fast);\r\n}\r\n\r\n.edit-receipt-btn {\r\n    border: 1px solid var(--color-accent-medium);\r\n    background-color: var(--color-accent-soft);\r\n    color: var(--color-accent);\r\n}\r\n\r\n    .edit-receipt-btn:hover {\r\n        background-color: var(--color-accent-medium);\r\n        border-color: var(--color-accent);\r\n        color: var(--color-accent);\r\n    }\r\n\r\n    .edit-receipt-btn:active {\r\n        transform: scale(0.98);\r\n    }\r\n\r\n.delete-receipt-btn {\r\n    border: 1px solid var(--color-danger-medium);\r\n    background-color: var(--color-danger-soft);\r\n    color: var(--color-danger);\r\n}\r\n\r\n    .delete-receipt-btn:hover {\r\n        background-color: var(--color-danger-medium);\r\n        border-color: var(--color-danger);\r\n        color: var(--color-danger);\r\n    }\r\n\r\n    .delete-receipt-btn:active {\r\n        transform: scale(0.98);\r\n    }\r\n\r\n    .back-btn:focus-visible,\r\n    .edit-receipt-btn:focus-visible,\r\n    .delete-receipt-btn:focus-visible {\r\n        outline: 2px solid var(--color-accent);\r\n        outline-offset: 2px;\r\n    }\r\n","/* src/components/PeriodSelector.css */\r\n\r\n.period-selector {\r\n    display: flex;\r\n    gap: var(--space-1);\r\n    margin-bottom: var(--space-6);\r\n    padding: var(--space-1);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-md);\r\n    background-color: var(--color-bg-inset);\r\n}\r\n\r\n.period-btn {\r\n    flex: 1;\r\n    min-width: 0;\r\n    padding: var(--space-3) var(--space-4);\r\n    border: none;\r\n    border-radius: var(--radius-sm);\r\n    background: none;\r\n    color: var(--color-text-tertiary);\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-semibold);\r\n    line-height: 1.2;\r\n    text-align: center;\r\n    white-space: nowrap;\r\n    cursor: pointer;\r\n    transition: background-color var(--transition-fast), color var(--transition-fast), box-shadow var(--transition-fast), transform var(--transition-fast);\r\n}\r\n\r\n    .period-btn.active {\r\n        background-color: var(--color-bg-surface);\r\n        color: var(--color-accent);\r\n        box-shadow: var(--shadow-sm);\r\n    }\r\n\r\n    .period-btn:active {\r\n        transform: scale(0.98);\r\n    }\r\n\r\n    .period-btn:focus-visible {\r\n        outline: 2px solid var(--color-accent);\r\n        outline-offset: 2px;\r\n    }\r\n\r\n@media (hover: hover) and (pointer: fine) {\r\n    .period-btn:hover {\r\n        color: var(--color-text-secondary);\r\n    }\r\n\r\n    .period-btn.active:hover {\r\n        color: var(--color-accent);\r\n    }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    .period-btn {\r\n        transition: none !important;\r\n    }\r\n}\r\n","/* src/components/CategoryBar.css */\r\n\r\n.category-bar {\r\n    padding: var(--space-4) 0;\r\n    border-bottom: 1px solid var(--color-border);\r\n    animation: cv-category-bar-in var(--transition-slow) both;\r\n}\r\n\r\n    .category-bar:last-child {\r\n        border-bottom: none;\r\n    }\r\n\r\n@keyframes cv-category-bar-in {\r\n    from {\r\n        opacity: 0;\r\n        transform: translateY(6px);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: translateY(0);\r\n    }\r\n}\r\n\r\n.category-bar-header {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    gap: var(--space-3);\r\n    margin-bottom: var(--space-2);\r\n}\r\n\r\n.category-bar-left {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: var(--space-2);\r\n    min-width: 0;\r\n    flex: 1 1 auto;\r\n}\r\n\r\n.category-bar-name {\r\n    min-width: 0;\r\n    overflow: hidden;\r\n    text-overflow: ellipsis;\r\n    white-space: nowrap;\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-semibold);\r\n    color: var(--color-text-primary);\r\n}\r\n\r\n.category-bar-count {\r\n    flex-shrink: 0;\r\n    font-size: var(--font-size-xs);\r\n    color: var(--color-text-tertiary);\r\n}\r\n\r\n.category-bar-amount {\r\n    flex-shrink: 0;\r\n    margin-left: var(--space-3);\r\n    font-family: var(--font-family-mono);\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-bold);\r\n    color: var(--color-text-primary);\r\n    text-align: right;\r\n}\r\n\r\n/* ��������-��� */\r\n.category-bar-track {\r\n    position: relative;\r\n    height: 8px;\r\n    overflow: hidden;\r\n    border-radius: var(--radius-pill);\r\n    background-color: var(--color-bg-inset);\r\n}\r\n\r\n.category-bar-fill {\r\n    height: 100%;\r\n    width: 100%;\r\n    min-width: 0;\r\n    border-radius: inherit;\r\n    transform: scaleX(0);\r\n    transform-origin: left center;\r\n    transition: transform var(--transition-slow), background-color var(--transition-fast), opacity var(--transition-fast);\r\n    will-change: transform, opacity;\r\n}\r\n\r\n.category-bar-percent {\r\n    margin-top: var(--space-1);\r\n    text-align: right;\r\n    font-family: var(--font-family-mono);\r\n    font-size: var(--font-size-xs);\r\n    color: var(--color-text-tertiary);\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    .category-bar,\r\n    .category-bar-fill {\r\n        animation: none !important;\r\n        transition: none !important;\r\n    }\r\n}\r\n",".statistics {\r\n    padding-bottom: var(--space-8);\r\n}\r\n\r\n/* --- �������� ����� ����� --- */\r\n\r\n.stats-summary {\r\n    background-color: var(--color-bg-surface);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-xl);\r\n    padding: var(--space-6);\r\n    margin-bottom: var(--space-8);\r\n    text-align: center;\r\n    box-shadow: var(--shadow-sm);\r\n    animation: cv-fade-in-up var(--transition-slow) both;\r\n}\r\n\r\n.stats-summary-label {\r\n    font-size: var(--font-size-sm);\r\n    color: var(--color-text-tertiary);\r\n    margin-bottom: var(--space-2);\r\n}\r\n\r\n.stats-summary-amount {\r\n    font-family: var(--font-family-mono);\r\n    font-size: var(--font-size-3xl);\r\n    font-weight: var(--font-weight-bold);\r\n    color: var(--color-accent);\r\n    margin-bottom: var(--space-2);\r\n    letter-spacing: var(--letter-spacing-tight);\r\n}\r\n\r\n.stats-summary-details {\r\n    display: flex;\r\n    gap: var(--space-2);\r\n    justify-content: center;\r\n    flex-wrap: wrap;\r\n    font-size: var(--font-size-sm);\r\n    color: var(--color-text-tertiary);\r\n}\r\n\r\n/* --- ������ ��� ���������� --- */\r\n\r\n.stats-section-title {\r\n    font-size: var(--font-size-xs);\r\n    font-weight: var(--font-weight-semibold);\r\n    color: var(--color-text-tertiary);\r\n    margin: 0 0 var(--space-4) 0;\r\n    text-transform: uppercase;\r\n    letter-spacing: var(--letter-spacing-caps);\r\n}\r\n\r\n.stats-categories {\r\n    background-color: var(--color-bg-surface);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-lg);\r\n    padding: var(--space-3) var(--space-5);\r\n    margin-bottom: var(--space-8);\r\n    box-shadow: var(--shadow-xs);\r\n}\r\n\r\n/* --- ������� �� ��� --- */\r\n\r\n.stats-average {\r\n    background-color: var(--color-bg-surface);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-lg);\r\n    padding: var(--space-5) var(--space-6);\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    gap: var(--space-3);\r\n    flex-wrap: wrap;\r\n    box-shadow: var(--shadow-xs);\r\n    animation: cv-fade-in-up 400ms ease-out both;\r\n    animation-delay: 200ms;\r\n}\r\n\r\n.stats-average-label {\r\n    font-size: var(--font-size-sm);\r\n    color: var(--color-text-secondary);\r\n}\r\n\r\n.stats-average-amount {\r\n    font-family: var(--font-family-mono);\r\n    font-size: var(--font-size-xl);\r\n    font-weight: var(--font-weight-bold);\r\n    color: var(--color-text-primary);\r\n    margin-left: auto;\r\n}\r\n","/* src/components/StorageIndicator.css */\r\n\r\n.storage-indicator {\r\n    background-color: var(--color-bg-surface);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-lg);\r\n    padding: var(--space-5);\r\n    margin-bottom: var(--space-8);\r\n    box-shadow: var(--shadow-xs);\r\n}\r\n\r\n.storage-header {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    margin-bottom: var(--space-1);\r\n}\r\n\r\n.storage-title {\r\n    font-size: var(--font-size-xs);\r\n    font-weight: var(--font-weight-semibold);\r\n    color: var(--color-text-tertiary);\r\n    text-transform: uppercase;\r\n    letter-spacing: var(--letter-spacing-caps);\r\n}\r\n\r\n.storage-values {\r\n    font-size: var(--font-size-xs);\r\n    color: var(--color-text-tertiary);\r\n    font-weight: var(--font-weight-medium);\r\n    font-family: var(--font-family-mono);\r\n}\r\n\r\n/* ��������-��� */\r\n.storage-bar {\r\n    height: 6px;\r\n    background-color: var(--color-bg-inset);\r\n    border-radius: var(--radius-pill);\r\n    overflow: hidden;\r\n    margin-bottom: var(--space-3);\r\n}\r\n\r\n.storage-bar-fill {\r\n    height: 100%;\r\n    border-radius: var(--radius-pill);\r\n    background-color: var(--color-accent);\r\n    transition: width var(--transition-slow), background-color var(--transition-slow);\r\n    min-width: 2px;\r\n}\r\n\r\n/* ����� �� ������� ������������� */\r\n.storage-bar-fill--warning {\r\n    background-color: var(--color-warning);\r\n}\r\n\r\n.storage-bar-fill--danger {\r\n    background-color: var(--color-danger);\r\n}\r\n\r\n.storage-footer {\r\n    font-size: var(--font-size-xs);\r\n    color: var(--color-text-tertiary);\r\n}\r\n","/* src/components/ThemeSelector.css */\r\n\r\n.theme-selector {\r\n    background-color: var(--color-bg-surface);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-lg);\r\n    padding: var(--space-4);\r\n    margin-bottom: var(--space-8);\r\n    box-shadow: var(--shadow-xs);\r\n}\r\n\r\n.theme-selector-title {\r\n    font-size: var(--font-size-xs);\r\n    font-weight: var(--font-weight-semibold);\r\n    color: var(--color-text-tertiary);\r\n    text-transform: uppercase;\r\n    letter-spacing: var(--letter-spacing-caps);\r\n    margin-bottom: var(--space-3);\r\n}\r\n\r\n.theme-selector-options {\r\n    display: flex;\r\n    gap: var(--space-3);\r\n}\r\n\r\n.theme-option {\r\n    flex: 1;\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    gap: var(--space-2);\r\n    padding: var(--space-3);\r\n    border: 2px solid var(--color-border);\r\n    border-radius: var(--radius-md);\r\n    background: none;\r\n    cursor: pointer;\r\n    transition: all var(--transition-fast);\r\n}\r\n\r\n    .theme-option:hover {\r\n        border-color: var(--color-border-hover);\r\n    }\r\n\r\n    .theme-option.active {\r\n        border-color: var(--color-accent);\r\n        background-color: var(--color-accent-soft);\r\n    }\r\n\r\n/* ������ ������ ���� */\r\n.theme-preview {\r\n    width: 40px;\r\n    height: 40px;\r\n    border-radius: var(--radius-sm);\r\n    display: flex;\r\n    overflow: hidden;\r\n    border: 1px solid var(--color-border);\r\n}\r\n\r\n.theme-preview-bg {\r\n    flex: 1;\r\n}\r\n\r\n.theme-preview-accent {\r\n    width: 12px;\r\n}\r\n\r\n/* ���������� ������ */\r\n.theme-preview--light .theme-preview-bg {\r\n    background-color: #FAF7F2;\r\n}\r\n\r\n.theme-preview--light .theme-preview-accent {\r\n    background-color: #21A038;\r\n}\r\n\r\n.theme-preview--dark .theme-preview-bg {\r\n    background-color: #0A1A14;\r\n}\r\n\r\n.theme-preview--dark .theme-preview-accent {\r\n    background-color: #4ADE80;\r\n}\r\n\r\n.theme-preview--midnight .theme-preview-bg {\r\n    background-color: #0F172A;\r\n}\r\n\r\n.theme-preview--midnight .theme-preview-accent {\r\n    background-color: #38BDF8;\r\n}\r\n\r\n.theme-option-label {\r\n    font-size: var(--font-size-xs);\r\n    font-weight: var(--font-weight-medium);\r\n    color: var(--color-text-secondary);\r\n}\r\n\r\n.theme-option.active .theme-option-label {\r\n    color: var(--color-accent);\r\n    font-weight: var(--font-weight-semibold);\r\n}\r\n","/* src/pages/SettingsPage.css */\r\n\r\n.settings-page {\r\n\tpadding-bottom: var(--space-8);\r\n}\r\n\r\n/* --- Секции --- */\r\n\r\n.settings-section {\r\n\tmargin-bottom: var(--space-8);\r\n}\r\n\r\n.settings-section-title {\r\n\tfont-size: var(--font-size-xs);\r\n\tfont-weight: var(--font-weight-semibold);\r\n\tcolor: var(--color-text-tertiary);\r\n\ttext-transform: uppercase;\r\n\tletter-spacing: var(--letter-spacing-caps);\r\n\tmargin: 0 0 var(--space-2) 0;\r\n}\r\n\r\n.settings-section-hint {\r\n\tfont-size: var(--font-size-sm);\r\n\tcolor: var(--color-text-tertiary);\r\n\tmargin: 0 0 var(--space-3) 0;\r\n}\r\n\r\n/* --- Кнопки-карточки --- */\r\n\r\n.settings-btn {\r\n\twidth: 100%;\r\n\tdisplay: flex;\r\n\talign-items: center;\r\n\tgap: var(--space-4);\r\n\tpadding: var(--space-4) var(--space-5);\r\n\tbackground-color: var(--color-bg-surface);\r\n\tborder: 1px solid var(--color-border);\r\n\tborder-radius: var(--radius-lg);\r\n\tcolor: var(--color-text-primary);\r\n\tcursor: pointer;\r\n\ttext-align: left;\r\n\tmargin-bottom: var(--space-2);\r\n\tbox-shadow: var(--shadow-xs);\r\n\ttransition: background-color var(--transition-fast), border-color var(--transition-fast), box-shadow var(--transition-fast), transform var(--transition-fast), color var(--transition-fast);\r\n}\r\n\r\n\t.settings-btn:hover {\r\n\t\tbackground-color: var(--color-bg-surface-hover);\r\n\t\tborder-color: var(--color-border-hover);\r\n\t\tbox-shadow: var(--shadow-sm);\r\n\t}\r\n\r\n\t.settings-btn:active {\r\n\t\ttransform: scale(0.99);\r\n\t}\r\n\r\n.settings-btn-icon {\r\n\tflex-shrink: 0;\r\n\tcolor: var(--color-text-tertiary);\r\n}\r\n\r\n.settings-btn-text {\r\n\tdisplay: flex;\r\n\tflex-direction: column;\r\n\tgap: 2px;\r\n\tmin-width: 0;\r\n}\r\n\r\n.settings-btn-label {\r\n\tfont-size: var(--font-size-base);\r\n\tfont-weight: var(--font-weight-semibold);\r\n\tcolor: var(--color-text-primary);\r\n}\r\n\r\n.settings-btn-hint {\r\n\tfont-size: var(--font-size-xs);\r\n\tcolor: var(--color-text-tertiary);\r\n}\r\n\r\n/* --- Карточка обучения --- */\r\n\r\n.settings-learning-card {\r\n\tdisplay: flex;\r\n\talign-items: center;\r\n\tgap: var(--space-4);\r\n\tpadding: var(--space-4) var(--space-5);\r\n\tmargin-bottom: var(--space-3);\r\n\tborder: 1px solid var(--color-border);\r\n\tborder-radius: var(--radius-lg);\r\n\tbackground-color: var(--color-bg-surface);\r\n\tbox-shadow: var(--shadow-xs);\r\n}\r\n\r\n.settings-learning-icon {\r\n\twidth: 40px;\r\n\theight: 40px;\r\n\tborder-radius: var(--radius-pill);\r\n\tdisplay: flex;\r\n\talign-items: center;\r\n\tjustify-content: center;\r\n\tflex-shrink: 0;\r\n\tbackground-color: var(--color-accent-soft);\r\n\tcolor: var(--color-accent);\r\n}\r\n\r\n.settings-learning-content {\r\n\tmin-width: 0;\r\n\tdisplay: flex;\r\n\tflex-direction: column;\r\n\tgap: 2px;\r\n}\r\n\r\n.settings-learning-title {\r\n\tfont-size: var(--font-size-sm);\r\n\tfont-weight: var(--font-weight-semibold);\r\n\tcolor: var(--color-text-primary);\r\n}\r\n\r\n.settings-learning-stats {\r\n\tdisplay: flex;\r\n\tflex-wrap: wrap;\r\n\tgap: var(--space-2);\r\n\tfont-size: var(--font-size-xs);\r\n\tcolor: var(--color-text-tertiary);\r\n}\r\n\r\n/* --- Опасная зона --- */\r\n\r\n.danger-zone {\r\n\tborder-top: 1px dashed var(--color-danger-medium);\r\n\tpadding-top: var(--space-6);\r\n}\r\n\r\n.settings-section.danger-zone .settings-section-title {\r\n\tcolor: var(--color-danger);\r\n}\r\n\r\n.settings-btn.danger-btn {\r\n\tborder-color: var(--color-danger-soft);\r\n}\r\n\r\n\t.settings-btn.danger-btn:hover {\r\n\t\tbackground-color: var(--color-danger-soft);\r\n\t\tborder-color: var(--color-danger-medium);\r\n\t}\r\n\r\n\t.settings-btn.danger-btn .settings-btn-icon {\r\n\t\tcolor: var(--color-danger);\r\n\t}\r\n\r\n\t.settings-btn.danger-btn .settings-btn-label {\r\n\t\tcolor: var(--color-danger);\r\n\t}\r\n\r\n/* --- О приложении --- */\r\n\r\n.settings-about {\r\n\tmargin-top: var(--space-12);\r\n\ttext-align: center;\r\n\tpadding: var(--space-6);\r\n}\r\n\r\n.settings-about-name {\r\n\tfont-size: var(--font-size-sm);\r\n\tfont-weight: var(--font-weight-semibold);\r\n\tcolor: var(--color-text-tertiary);\r\n\tmargin-bottom: var(--space-1);\r\n}\r\n\r\n.settings-about-desc {\r\n\tfont-size: var(--font-size-xs);\r\n\tcolor: var(--color-text-placeholder);\r\n}\r\n\r\n/* --- Диалог импорта --- */\r\n\r\n.import-dialog {\r\n\tmax-width: 400px;\r\n}\r\n\r\n.import-buttons {\r\n\tdisplay: flex;\r\n\tflex-direction: column;\r\n\tgap: var(--space-2);\r\n\tmargin-bottom: var(--space-3);\r\n}\r\n\r\n.import-btn {\r\n\twidth: 100%;\r\n\tpadding: var(--space-4);\r\n\tborder: 1px solid var(--color-border);\r\n\tborder-radius: var(--radius-md);\r\n\tbackground-color: var(--color-bg-surface);\r\n\tcolor: var(--color-text-primary);\r\n\tcursor: pointer;\r\n\ttext-align: left;\r\n\ttransition: background-color var(--transition-fast), border-color var(--transition-fast), box-shadow var(--transition-fast), transform var(--transition-fast), color var(--transition-fast);\r\n}\r\n\r\n\t.import-btn:hover {\r\n\t\tbackground-color: var(--color-bg-surface-hover);\r\n\t\tborder-color: var(--color-border-hover);\r\n\t}\r\n\r\n.import-btn-label {\r\n\tdisplay: block;\r\n\tfont-size: var(--font-size-sm);\r\n\tfont-weight: var(--font-weight-semibold);\r\n\tmargin-bottom: 2px;\r\n}\r\n\r\n.import-btn-hint {\r\n\tdisplay: block;\r\n\tfont-size: var(--font-size-xs);\r\n\tcolor: var(--color-text-tertiary);\r\n}\r\n\r\n.replace-btn {\r\n\tborder-color: var(--color-danger-medium);\r\n}\r\n\r\n\t.replace-btn:hover {\r\n\t\tborder-color: var(--color-danger);\r\n\t\tbackground-color: var(--color-danger-soft);\r\n\t}\r\n\r\n.import-cancel {\r\n\twidth: 100%;\r\n\tpadding: var(--space-3);\r\n\tbackground: none;\r\n\tborder: none;\r\n\tcolor: var(--color-text-tertiary);\r\n\tfont-size: var(--font-size-sm);\r\n\tfont-weight: var(--font-weight-medium);\r\n\tcursor: pointer;\r\n\tborder-radius: var(--radius-sm);\r\n\ttransition: color var(--transition-fast), background-color var(--transition-fast);\r\n}\r\n\r\n\t.import-cancel:hover {\r\n\t\tcolor: var(--color-text-primary);\r\n\t\tbackground-color: var(--color-bg-inset);\r\n\t}\r\n\r\n\t.settings-btn:focus-visible,\r\n\t.import-btn:focus-visible,\r\n\t.import-cancel:focus-visible {\r\n\t\toutline: 2px solid var(--color-accent);\r\n\t\toutline-offset: 2px;\r\n\t}\r\n","/* src/components/NavigationBar.css */\r\n\r\n.navigation-bar {\r\n    position: fixed;\r\n    top: 0;\r\n    left: 0;\r\n    right: 0;\r\n    z-index: 100;\r\n    display: flex;\r\n    height: var(--nav-height);\r\n    border-bottom: 1px solid var(--color-border);\r\n    box-shadow: var(--shadow-sm);\r\n    background-color: rgba(255, 255, 255, 0.84);\r\n    backdrop-filter: blur(10px);\r\n    -webkit-backdrop-filter: blur(10px);\r\n}\r\n\r\n[data-theme=\"dark\"] .navigation-bar,\r\n[data-theme=\"midnight\"] .navigation-bar {\r\n    background-color: rgba(18, 18, 22, 0.84);\r\n}\r\n\r\n.nav-tab {\r\n    position: relative;\r\n    flex: 1;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    gap: var(--space-2);\r\n    height: 100%;\r\n    padding: 0 var(--space-2);\r\n    border: none;\r\n    background: none;\r\n    color: var(--color-text-tertiary);\r\n    font-size: var(--font-size-sm);\r\n    cursor: pointer;\r\n    transition: color var(--transition-fast), background-color var(--transition-fast);\r\n}\r\n\r\n    .nav-tab:focus-visible {\r\n        outline: 2px solid var(--color-accent);\r\n        outline-offset: -2px;\r\n    }\r\n\r\n@media (hover: hover) and (pointer: fine) {\r\n    .nav-tab:hover {\r\n        color: var(--color-text-secondary);\r\n        background-color: var(--color-bg-inset);\r\n    }\r\n}\r\n\r\n.nav-tab.active {\r\n    color: var(--color-accent);\r\n}\r\n\r\n    .nav-tab.active::after {\r\n        content: '';\r\n        position: absolute;\r\n        left: 50%;\r\n        bottom: 0;\r\n        width: 32px;\r\n        height: 3px;\r\n        border-radius: var(--radius-pill) var(--radius-pill) 0 0;\r\n        background-color: currentColor;\r\n        transform: translateX(-50%);\r\n        pointer-events: none;\r\n    }\r\n\r\n.nav-icon {\r\n    flex-shrink: 0;\r\n    display: block;\r\n}\r\n\r\n.nav-label {\r\n    font-weight: var(--font-weight-semibold);\r\n    letter-spacing: var(--letter-spacing-wide);\r\n    white-space: nowrap;\r\n}\r\n\r\n@media (max-width: 380px) {\r\n    .nav-label {\r\n        display: none;\r\n    }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    .nav-tab {\r\n        transition: none !important;\r\n    }\r\n}\r\n","/* src/components/Notification.css */\r\n\r\n.notification {\r\n    --notification-duration: 3000ms;\r\n    position: fixed;\r\n    top: calc(var(--nav-height) + var(--space-3));\r\n    left: 50%;\r\n    z-index: 1000;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: var(--space-3);\r\n    width: min(420px, calc(100% - var(--space-6)));\r\n    padding: var(--space-4) var(--space-5);\r\n    border: 1px solid transparent;\r\n    border-left-width: 4px;\r\n    border-radius: var(--radius-lg);\r\n    background-color: var(--color-bg-elevated);\r\n    color: var(--color-text-primary);\r\n    box-shadow: var(--shadow-lg);\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-medium);\r\n    line-height: 1.4;\r\n    overflow: hidden;\r\n    transform: translateX(-50%);\r\n    animation: cv-notification-in 240ms cubic-bezier(0.34, 1.56, 0.64, 1) both;\r\n}\r\n\r\n@keyframes cv-notification-in {\r\n    from {\r\n        opacity: 0;\r\n        transform: translateX(-50%) translateY(-8px) scale(0.98);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: translateX(-50%) translateY(0) scale(1);\r\n    }\r\n}\r\n\r\n/* ��������-��� */\r\n.notification::after {\r\n    content: '';\r\n    position: absolute;\r\n    left: 0;\r\n    right: 0;\r\n    bottom: 0;\r\n    height: 3px;\r\n    transform-origin: left center;\r\n    animation: cv-notification-progress var(--notification-duration) linear both;\r\n}\r\n\r\n@keyframes cv-notification-progress {\r\n    from {\r\n        transform: scaleX(1);\r\n    }\r\n\r\n    to {\r\n        transform: scaleX(0);\r\n    }\r\n}\r\n\r\n/* ���� */\r\n.notification--success {\r\n    border-color: var(--color-success);\r\n    border-left-color: var(--color-success);\r\n}\r\n\r\n    .notification--success::after {\r\n        background-color: var(--color-success);\r\n    }\r\n\r\n    .notification--success .notification-icon {\r\n        color: var(--color-success);\r\n    }\r\n\r\n.notification--error {\r\n    border-color: var(--color-danger);\r\n    border-left-color: var(--color-danger);\r\n}\r\n\r\n    .notification--error::after {\r\n        background-color: var(--color-danger);\r\n    }\r\n\r\n    .notification--error .notification-icon {\r\n        color: var(--color-danger);\r\n    }\r\n\r\n.notification--warning {\r\n    border-color: var(--color-warning);\r\n    border-left-color: var(--color-warning);\r\n}\r\n\r\n    .notification--warning::after {\r\n        background-color: var(--color-warning);\r\n    }\r\n\r\n    .notification--warning .notification-icon {\r\n        color: var(--color-warning);\r\n    }\r\n\r\n/* �������� */\r\n.notification-icon {\r\n    flex-shrink: 0;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n}\r\n\r\n    .notification-icon svg {\r\n        display: block;\r\n    }\r\n\r\n.notification-message {\r\n    flex: 1;\r\n    min-width: 0;\r\n}\r\n\r\n.notification-close {\r\n    flex-shrink: 0;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    padding: var(--space-1);\r\n    border: none;\r\n    border-radius: var(--radius-sm);\r\n    background: none;\r\n    color: var(--color-text-tertiary);\r\n    cursor: pointer;\r\n    transition: color var(--transition-fast), background-color var(--transition-fast), transform var(--transition-fast);\r\n}\r\n\r\n@media (hover: hover) and (pointer: fine) {\r\n    .notification-close:hover {\r\n        color: var(--color-text-primary);\r\n        background-color: var(--color-bg-inset);\r\n    }\r\n}\r\n\r\n.notification-close:active {\r\n    transform: scale(0.96);\r\n}\r\n\r\n.notification-close:focus-visible {\r\n    outline: 2px solid var(--color-accent);\r\n    outline-offset: 2px;\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    .notification,\r\n    .notification::after,\r\n    .notification-close {\r\n        animation: none !important;\r\n        transition: none !important;\r\n    }\r\n}\r\n","/* src/components/CategoryDebugPanel.css */\r\n\r\n.category-debug-panel {\r\n    margin-top: var(--space-6);\r\n    padding: var(--space-4);\r\n    border: 1px dashed var(--color-border-hover);\r\n    border-radius: var(--radius-lg);\r\n    background-color: var(--color-bg-surface);\r\n    box-shadow: var(--shadow-xs);\r\n}\r\n\r\n.category-debug-title {\r\n    font-size: var(--font-size-xs);\r\n    font-weight: var(--font-weight-bold);\r\n    text-transform: uppercase;\r\n    letter-spacing: var(--letter-spacing-caps);\r\n    color: var(--color-text-tertiary);\r\n    margin-bottom: var(--space-3);\r\n}\r\n\r\n.category-debug-section + .category-debug-section {\r\n    margin-top: var(--space-4);\r\n    padding-top: var(--space-4);\r\n    border-top: 1px dashed var(--color-border);\r\n}\r\n\r\n.category-debug-subtitle {\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-semibold);\r\n    color: var(--color-text-primary);\r\n    margin-bottom: var(--space-2);\r\n}\r\n\r\n.category-debug-empty {\r\n    font-size: var(--font-size-sm);\r\n    color: var(--color-text-tertiary);\r\n}\r\n\r\n.category-debug-list {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: var(--space-2);\r\n}\r\n\r\n.category-debug-item {\r\n    padding: var(--space-3);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-md);\r\n    background-color: var(--color-bg-inset);\r\n}\r\n\r\n.category-debug-item--candidate {\r\n    background-color: var(--color-bg-surface);\r\n}\r\n\r\n.category-debug-item-title {\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-semibold);\r\n    color: var(--color-text-primary);\r\n    margin-bottom: 4px;\r\n}\r\n\r\n.category-debug-item-meta {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    gap: var(--space-2);\r\n    font-size: var(--font-size-xs);\r\n    color: var(--color-text-secondary);\r\n}\r\n\r\n    .category-debug-item-meta strong {\r\n        color: var(--color-text-primary);\r\n        font-weight: var(--font-weight-semibold);\r\n    }\r\n\r\n.category-debug-candidate-top {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    gap: var(--space-2);\r\n    margin-bottom: var(--space-2);\r\n}\r\n\r\n.category-debug-candidate-pattern {\r\n    font-family: var(--font-family-mono);\r\n    font-size: var(--font-size-sm);\r\n    font-weight: var(--font-weight-semibold);\r\n    color: var(--color-accent);\r\n}\r\n\r\n.category-debug-candidate-badge {\r\n    flex-shrink: 0;\r\n    padding: 2px 8px;\r\n    border-radius: var(--radius-pill);\r\n    background-color: var(--color-accent-soft);\r\n    color: var(--color-accent);\r\n    font-size: var(--font-size-xs);\r\n    font-weight: var(--font-weight-medium);\r\n}\r\n\r\n.category-debug-examples {\r\n    margin-top: var(--space-2);\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 4px;\r\n}\r\n\r\n.category-debug-example {\r\n    font-size: var(--font-size-xs);\r\n    color: var(--color-text-secondary);\r\n}\r\n\r\n.category-debug-actions {\r\n    margin-top: var(--space-3);\r\n    display: flex;\r\n    gap: var(--space-2);\r\n}\r\n\r\n.category-debug-btn {\r\n    height: 32px;\r\n    padding: 0 var(--space-3);\r\n    border: 1px solid var(--color-border);\r\n    border-radius: var(--radius-pill);\r\n    background-color: var(--color-bg-surface);\r\n    color: var(--color-text-primary);\r\n    font-size: var(--font-size-xs);\r\n    font-weight: var(--font-weight-medium);\r\n    cursor: pointer;\r\n    transition: background-color var(--transition-fast), border-color var(--transition-fast), color var(--transition-fast);\r\n}\r\n\r\n    .category-debug-btn:hover:not(:disabled) {\r\n        background-color: var(--color-bg-surface-hover);\r\n        border-color: var(--color-border-hover);\r\n    }\r\n\r\n    .category-debug-btn:disabled {\r\n        opacity: 0.55;\r\n        cursor: default;\r\n    }\r\n\r\n.category-debug-btn--danger {\r\n    color: var(--color-danger);\r\n    border-color: var(--color-danger-medium);\r\n    background-color: var(--color-danger-soft);\r\n}\r\n\r\n    .category-debug-btn--danger:hover:not(:disabled) {\r\n        border-color: var(--color-danger);\r\n        background-color: var(--color-danger-medium);\r\n    }\r\n","/* src/components/ErrorBoundary.css */\r\n\r\n.error-boundary {\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    justify-content: center;\r\n    min-height: 60vh;\r\n    padding: var(--space-8);\r\n    text-align: center;\r\n}\r\n\r\n.error-boundary-icon {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    flex-shrink: 0;\r\n    width: 80px;\r\n    height: 80px;\r\n    margin-bottom: var(--space-6);\r\n    border: 1px solid var(--color-danger-medium);\r\n    border-radius: 999px;\r\n    background-color: var(--color-danger-soft);\r\n    color: var(--color-danger);\r\n}\r\n\r\n    .error-boundary-icon svg {\r\n        display: block;\r\n    }\r\n\r\n.error-boundary-title {\r\n    margin-bottom: var(--space-2);\r\n    font-size: var(--font-size-xl);\r\n    font-weight: var(--font-weight-bold);\r\n    line-height: 1.2;\r\n    color: var(--color-text-primary);\r\n}\r\n\r\n.error-boundary-message {\r\n    max-width: 320px;\r\n    margin-bottom: var(--space-6);\r\n    font-size: var(--font-size-sm);\r\n    line-height: var(--line-height-relaxed);\r\n    color: var(--color-text-secondary);\r\n}\r\n\r\n.error-boundary-btn {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: var(--space-2);\r\n    padding: var(--space-3) var(--space-6);\r\n    border: none;\r\n    border-radius: var(--radius-md);\r\n    background-color: var(--color-accent);\r\n    color: var(--color-text-inverse);\r\n    font-size: var(--font-size-base);\r\n    font-weight: var(--font-weight-semibold);\r\n    cursor: pointer;\r\n    transition: background-color var(--transition-fast), transform var(--transition-fast);\r\n}\r\n\r\n    .error-boundary-btn:hover {\r\n        background-color: var(--color-accent-hover);\r\n    }\r\n\r\n    .error-boundary-btn:active {\r\n        transform: scale(0.98);\r\n    }\r\n\r\n    .error-boundary-btn:focus-visible {\r\n        outline: 2px solid var(--color-accent);\r\n        outline-offset: 2px;\r\n    }\r\n\r\n.error-boundary-details {\r\n    width: 100%;\r\n    max-width: 420px;\r\n    margin-top: var(--space-6);\r\n    padding: var(--space-4);\r\n    border-radius: var(--radius-sm);\r\n    background-color: var(--color-bg-inset);\r\n    text-align: left;\r\n}\r\n\r\n    .error-boundary-details summary {\r\n        cursor: pointer;\r\n        font-size: var(--font-size-xs);\r\n        color: var(--color-text-tertiary);\r\n    }\r\n\r\n    .error-boundary-details pre {\r\n        margin-top: var(--space-2);\r\n        max-height: 140px;\r\n        overflow-y: auto;\r\n        font-family: var(--font-family-mono);\r\n        font-size: var(--font-size-xs);\r\n        line-height: 1.5;\r\n        color: var(--color-danger);\r\n        white-space: pre-wrap;\r\n        word-break: break-word;\r\n    }\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    .error-boundary-btn {\r\n        transition: none !important;\r\n    }\r\n}\r\n"],"names":[],"sourceRoot":""}